SELECT 'moj-all-verified-judgments-review-002-chunk-045' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7ffe0ca6-6a9e-5f26-b9ac-d4026ba227d7","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالتلفظ يف صحيفة دعوى - مطالبة املدعي باملجازاة -انكار وكيل املدعى عليه الدعوى عنه -عدم مسؤولية الوكيل عن عبارات السب التي أوردها موكله يف صحيفة الدعوى -رد الدعوى.","document_number":"34329653","case_number":"3497172","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/13","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالتلفظ يف صحيفة دعوى - مطالبة املدعي باملجازاة -انكار وكيل املدعى عليه الدعوى عنه -عدم مسؤولية الوكيل عن عبارات السب التي أوردها موكله يف صحيفة الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/13 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34329653 :‬‬\n                           ‫َر ْق ُم الدعوى‪3497172 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34383132‬تاريخه‪1434/2/22 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالتلفــظ يف صحيفــة دعــوى ‪-‬‬\n       ‫مطالبــة املدعــي باملجــازاة ‪ -‬انــكار وكيــل املدعــى عليــه الدعــوى عنــه‬\n       ‫‪ -‬عــدم مســؤولية الوكيــل عــن عبــارات الســب التــي أوردهــا موكلــه يف‬\n                                                ‫صحيفــة الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n                                        ‫قول اهلل تعالى‪ (( :‬وال تزر وازرة وزر أخرى ))‪.‬‬\n\n\n\n\n       ‫ادعــى وكيــل املدعــي علــى املدعــى عليــه بأنــه قــد تلفــظ علــى موكلــه‬\n       ‫مبــا جــاء يف دعــواه وذلــك يف صحيفــة دعــوى قدمهــا إلــى احملكمــة‬\n       ‫تتعلــق بقضيــة حضانــة بــن موكلــه وزوجتــه‪ ،‬وطلــب احلكــم عليــه‬\n       ‫بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر وكيــل املدعــى عليــه مــا جــاء يف‬\n       ‫دعــوى املدعــي ودفــع بــأن موكلــه ناقــل لوجهــة نظــر موكلتــه (يف قضية‬\n       ‫احلضانــة) ودوره هــو متثيلهــا يف الدعــوى‪ ،‬كمــا أن الصحيفــة املذكــورة‬\n       ‫ليســت مــن إعــداده بــل مــن إعــداد موكلتــه وبالتالــي فــا يوجــد ســبب‬\n       ‫الختصــام املدعــي مــع موكلــه‪ -‬املدعــى عليــه ال يتكلــم عــن نفســه‬\n       ‫وإمنــا ناقــل لوجهــة نظــر موكلتــه‪ -‬قضــت احملكمــة بصــرف النظــر عــن‬\n       ‫دعــوى املدعــي‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي ‪ -‬قــررت‬\n\n‫‪201‬‬\n\f             ‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 3497172‬وتاريــخ ‪1434/02/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34503559‬وتاريــخ ‪1434/2/27‬ه ـ ففــي يوم اخلميس‬\n‫املوافــق ‪1434/08/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 :15‬وفيهــا حضــر‬\n‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).....‬وكيــا عــن‬\n‫مبوجــب الوكالــة رقــم (‪ )34130943‬وتاريــخ ‪1434/02/04‬ه ـ والتــي‬\n‫تخــول لــه املرافعــة واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار‬\n‫والصلــح والتنــازل وطلــب اليمــن ورده واالمتنــاع عنــه واملطالبــة بتنفيــذ‬\n‫األحــكام وقبولهــا والــرد عليهــا واالعتــراض عليهــا وطلــب االســتئناف‬\n‫وادعــى علــى احلاضــر معــه‪ ).....( /‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).....‬مبوجــب الوكالــة رقــم (‪ )34345133‬وتاريــخ‬\n‫‪1434/3/21‬ه والتــي تخــول لــه املرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل واإلبــراء وطلــب‬\n‫اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا‬\n‫والتنفيــذ وطلــب التحكيــم واملطالبــة بتنفيــذ األحــكام وقبــول احلكــم‬\n‫ونفيهــا واالعتــراض علــى األحــكام وطلــب االســتئناف قائــا يف دعــواه‬\n‫إن مــوكل هــذا احلاضــر قــد تلفــظ علــى موكلــي يف صحيفــة الدعــوى‬\n‫املقدمــة يف احملكمــة العامــة يف الريــاض لــدى فضيلة القاضي يف دعوى‬\n‫حضانــة وأتهمــه بالتواطــؤ مــع الشــيطان يف حتقيــق مــراده وانشــغاله‬\n\n                                                                                   ‫‪202‬‬\n\f      ‫يف شــهوات ملــذات الدنيــا حتــى أصبــح عــدمي االحســاس باألبــوة وأنــه‬\n      ‫متجــرد مــن الشــفقة واالنســانية وإنــي تعهــدت بإصــاح نفســي ونكثــت‬\n      ‫عــن الشــرط أطلــب مجازاتــه علــى هــذا االتهــام وبســؤال املدعــى عليــه‬\n      ‫أجــاب مــا ذكــره املدعــي كلــه غيــر صحيــح و يدفــع موكلــي بدفعــه‬\n      ‫الشــكلي ألن الدعــوى أقيمــت علــى مــن ال يصــح اختصامــه حيــث أن‬\n      ‫ـام وقــد تــوكل عــن الســيدة‪ ).....(/‬مبوجــب الوكالــة‬   ‫موكلــي يعمــل محـ ٍ‬\n      ‫رقــم ‪ 3470551‬وتاريــخ ‪1434/1/19‬ه ـ ومثلهــا يف قضيتــن األولــى‬\n      ‫حضانــة والثانيــة نفقــة واملنظــورة لــدى فضيلــة الشــيخ‪ ).....(/‬القاضــي‬\n      ‫باحملكمــة العامــة بالريــاض وبالتالــي فــإن موكلــي هــو ناقــل لوجهــة‬\n      ‫نظــر موكلتــه وكمــا يعلــم فضيلتكــم أن الوكيــل ال يكلــف وال‬\n      ‫يحلــف إذ أن دوره هــو متثيــل ملوكلــه وناقــل ألقوالــه‪ ،‬والدليــل علــى ذلــك‬\n      ‫مــا ورد صريح ـ ًا يف نــص املــادة (‪ )13‬مــن نظــام احملامــاة والتــي تنــص‬\n      ‫علــى « للمحامــي أن يســلك الطريقــة التــي يراهــا ناجحــة يف الدفــاع عــن‬\n      ‫موكلــه‪ ،‬وال جتــوز مســاءلته عمــا يــورده يف مرافعته كتابي ًا أو مشــافهة‬\n      ‫ممــا يســتلزمه حــق الدفــاع « ولــم يحيــد موكلــي عمــا نــص عليــه نظــام‬\n      ‫احملامــاة وموكلــي ملتــزم متامـ ًا مبــا مت ضبطــه يف صــك احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ ).....( /‬قضيــة احلضانــة وهــو مســئول عمــا يــرد يف‬\n      ‫ضبــط اجللســة دون ســواه‪ ،‬لــذا فــإن موكلــي يتمســك بالدفــع الشــكلي‪.‬‬\n      ‫ثانيـاً‪ :‬مــن حيــث املوضــوع‪ :‬يف البدايــة يتمســك موكلــي بإقــرار املدعــي‬\n      ‫يف مجلــس القضــاء علــى صحــة دعــوى موكلتــه يف احلضانــة والتــي صدر‬\n      ‫بهــا الصــك رقــم (‪ )3432451‬وتاريــخ ‪1434/2/9‬ه ـ حيــث أنــه أقــر‬\n      ‫وأكــد صحــة دعــوى موكلــة موكلــي فيمــا ذكرتــه‪ .1.‬مــن الواضــح‬\n      ‫أن املدعــي أقــام هــذه الدعــوى بعــد صــدور حكــم احلضانــة لصالــح‬\n\n\n‫‪203‬‬\n\f‫موكلــة موكلــي رغبــة مــن املدعــي لثنــي موكلــي عــن مواصلــة القضيــة‬\n‫الثانيــة (النفقــة) والتــي ال تــزال منظــورة يف احملكمــة العامــة لــدى‬\n‫فضيلــة القاضــي ‪ .2‬مــا ارتكــن عليــه املدعــي يف مذكرتــه مــن صــدور‬\n‫مذكــرة قدمــت يف قضيــة احلضانــة فاملذكــرة ال حتمــل أي توقيــع عليها‬\n‫مــن موكلــي والواضــح أن موكلــة موكلــي قامــت بإعــداد املذكــرة‬\n‫ـاء علــى رغبتهــا بدليــل أنهــا علــى‬\n                                    ‫والتوقيــع عليهــا وأحضرهــا ملوكلــي بنـ ً‬\n‫أوراق بيضــاء وليســت علــى مطبوعــات احملامــي الرســمية باإلضافــة‬\n‫إلــى ذلــك درجــت العــادة أن قضايــا األحــوال الشــخصية تتــم مرافعتهــا‬\n‫شــفوي ًا أمــام ناظــر القضيــة حيــث أنهــا مــن القضايــا البســيطة كمــا‬\n‫هــو موضــح يف الصــك مــن القاضــي‪ .3 .‬بالرجــوع إلــى الئحــة الدعــوى‬\n‫محــل الــرد لــم جنــد حتديــد ًا للعبــارات بنــص صريــح وإمنــا ذكــر بعــض‬\n‫العبــارات وأورد معهــا تفســير ًا خاص ـ ًا باملدعــي وموكلــي ال يتحمــل أي‬\n‫تفســير إال مــا يصــدر منــه ال ســيما وأن تلــك العبــارات لــم متــس ذات‬\n‫املدعــي وســوف نــرد علــى مــا أورده مــن عبــارات وفــق تفســير موكلــة‬\n‫موكلــي باعتبــار أنهــا مــن كتبــت املذكــرة وهــي علــى النحــو اآلتــي‪ :‬أ‪.‬‬\n‫العبــارة اخلاصــة مــا أورده مــن تفســير أن موكلــي ذكــر أنــه متواطــئ مــع‬\n‫الشــيطان فهــذا قــول ال وجــود لــه إال لــدى املدعــي وحــده فقــط فاجلملــة‬\n‫املوجــودة يف املذكــرة هــي (حقــق مــراد الشــيطان بفعلــه) فنجــد أن‬\n‫املدعــي عمــد إلــى اقتضــاب اجلملــة وحتويرهــا بغيــر شــكلها األصلــي إذ‬\n‫أن املذكــرة التــي أخــذ منهــا نصــت مــا يلــي‪( :‬واســتجاب للشــيطان الــذي‬\n‫يريــد أن يــزرع الفتنــة والفــراق بــن األســر واملجتمعــات) فالــكالم هنــا‬\n‫ليــس لشــخص املدعــي وإمنــا قصــد بــه الشــيطان وذكــرت صفاتــه وأنــه‬\n‫بوجــود املشــاكل بــن املدعــي وموكلــة موكلــي هــو حتقيق ـ ًا لرغبــة‬\n\n\n                                                                                  ‫‪204‬‬\n\f      ‫الشــيطان لتفريــق األســرة واملجتمعــات‪ ،‬ومــن الواضــح مــن العبــارة التــي‬\n      ‫يف املذكــرة جــاءت للعــوام وليســت للتخصيــص لــذا فــإن هــذه العبــارة‬\n      ‫لــم تقصــد املدعــي بذاتــه‪ .‬ب‪ .‬أمــا مــا يخــص عبــارة (الشــهوات وامللــذات)‬\n      ‫فــإن هــذه عبــارة عائمــة فضفاضــة لــم يعنــي بهــا األمــور الســيئة فــكل مــا‬\n      ‫مييــل إليــه قلــب البشــر يعتبــر ملــذة وشــهوة‪ ،‬شــرب املــاء ملــذة‪ ،‬واالهتمــام‬\n      ‫بالدراســة ملــذة وشــهوة‪ ،‬وحــب املــال أيض ـ ًا وقــدوم اإلنســان علــى أمــر‬\n      ‫معــن يعتبــر ملهــي لــه ويعتبــر مــن ملــذات وشــهوات الدنيــا ومــا قصــد يف‬\n      ‫تلــك املذكــرة انكبــاب املدعــي يف عملــه ودراســته يف بريطانيــا وبعــده‬\n      ‫عــن أبنائــه وعــن أســرته وهــذا أمــر طبيعــي قــد يحصــل ألي شــخص‬\n      ‫متــزوج ولديــه أبنــاء فهــو مــن قبيــل االنشــغال بالشــهوات وملــذات النفــس‬\n      ‫املباحــة‪ ،‬لــذا فــان العبــارة ال تأخــذ باملعنــي الســيئ إذ أن ســياق القــول‬\n      ‫يفيــد انشــغال املدعــى بأحوالــه الشــخصية مــن دراســة وعمــل وليــس‬\n      ‫فيهــا أي تطــاول وكانــت مذكــورة مــن بــاب توضيــح الدفــوع لفضيلــة‬\n      ‫ناظــر القضيــة‪ .‬ج‪ .‬مســألة الوعــد والعهــد ونكثــه فــأي زوجــن قــد يقطــع‬\n      ‫لألخــر وعــد علــى نفســه بــأن ال يحــدث أي مشــاكل وحــال حصــول تلــك‬\n      ‫املشــاكل يعتبــر نكــث للوعــد‪ ،‬وموكلــة موكلــي رأت أن املدعــي قــد‬\n      ‫وعدهــا بعــدم حــدوث مشــاكل بينهمــا بــأن ال يعــود إلــى نفــس األســباب‬\n      ‫التــي تبعــث املشــاكل بينهمــا ولكــن ذلــك لــم يحصــل منــه وترتــب عليــه‬\n      ‫الطــاق واالنفصــال بينهمــا وقــد يكــون املدعــي فيــه نــوع مــن الغضــب‬\n      ‫أو التقصيــر وقــد وعــد موكلــة موكلــي بعــدم الغضــب أو التقصيــر إال‬\n      ‫انــه عــاد وحصــل اخلــاف فجعلــت ذلــك نكث ـ ًا للوعــود وللعهــود وليــس‬\n      ‫يف ذلــك أي تطــاول أو ســب‪ .‬د‪ .‬مــا يخــص مــا ذكــره املدعــي يف الئحتــه‬\n      ‫محــل الــرد وحتــت البنــد رقــم (‪ )5‬فــإن كل ذلــك جــاء بوصــف موكلــة‬\n\n\n‫‪205‬‬\n\f‫موكلــي ملــا حــدث لهــا مــن حرمــان مــن أبنائهــا أكثــر مــن ثمانيــة أشــهر‬\n‫دون أن تراهــم وكذلــك ســحبه مللفــات دراســتهم مــن املــدارس وتعطيلهم‬\n‫ا فــكان أقــرب وصــف لذلــك التصــرف مــا‬         ‫عــن الدراســة عام ـ ًا كام ـ ً‬\n‫ذكرتــه يف تلــك املذكــرة إن صحــة ذلــك‪ ،‬باإلضافــة إلــى غيــاب األب‬\n‫بالســفر للدراســة وتــرك األبنــاء لــدى اجلــد اعتبرتــه موكلــة موكلــي‬\n‫إهمــا ًال منــه وتقصيــر ًا بواجبــات األب مــا يخــص عبــارة « نســأل اهلل‬\n‫الســامة والعافيــة « فقــد ذكــرت كجملــة ختاميــة يف معــرض حديــث‬\n‫موكلــة موكلــي عــن حالهــا مــن امتنــاع املدعــي عــن النفقــة وحرمانهــا‬\n‫مــن أبنائهــا ونفقــات الــوالدة التــي لــم ينكرهــا املدعــي بــل أكدهــا‬\n‫بقولــه‪« :‬مــا ذكــره املدعــي وكالــة كلــه صحيــح جملــة وتفصيــا»‬\n‫وهــذه العبــارة يف حقيقتهــا دعــاء وتــودد ورجــاء مــن املولــى عــز وجــل‬\n‫تقــال يف الســراء والضــراء‪ .‬و‪ .‬يتضــح ملقــام فضيلتكــم أن موكلــي لــم‬\n‫يقــوم بالتطــاول علــى املدعــي أو ســبه أو حتــى املســاس بشــخصه وإمنــا‬\n‫هــو ناقــل عــن موكلتــه وكذلــك لــم يوجــد أي عبــارة مــن العبــارات التــي‬\n‫ذكرهــا فيهــا ســب لشــخص املدعــي وإمنــا عبــارات عاديــة ذكرتهــا‬\n‫موكلــة موكلــي لنقــل الصــورة التــي عانــت منهــا وكذلــك العبــارات‬\n‫ال حتمــل طابــع الســب أو التطــاول بــل طابــع الدفــاع عــن حقــوق موكلــة‬\n‫موكلــي ناهيــك انــه ال توجــد أي عالقــة أو ارتبــاط بــن املدعــى أصالــة‬\n‫وبــن موكلــي إال يف تلــك اجللســة التــي تقابــل فيهــا أول مــره وبالتالــي‬\n‫ال يوجــد أي ســبب شــرعي أو منطقــي يقبــل بــه خصومــة املدعــى مــع‬\n‫موكلــي‪ .‬ونؤكــد أن مــا ذكــر يف قضيــة احلضانــة والتــي كان يترافــع‬\n‫بهــا موكلــي قــد أقــر املدعــي يف تلــك اجللســة بــأن مــا ذكــر يف الدعــوى‬\n‫كلــه صحيــح جمل ـ ًة وتفصيــا‪ ،‬وهــذا إقــرار منــه بذلــك والقاعــدة‬\n\n\n                                                                                     ‫‪206‬‬\n\f      ‫الشــرعية تنــص (ال يجــوز اإلنــكار بعــد اإلقــرار إذ ال عــذر ملــن أقــر)‬\n      ‫وبإقــراره يف مجلــس القضــاء يثبــت مبــا ال يــدع مجــا ًال للشــك أن مــا نقلــه‬\n      ‫موكلــي صحيــح جمل ـ ًة وتفصي ـاً‪ .‬عليــه ولــكل مــا تقــدم التمــس مــن‬\n      ‫ال لعــدم وجــود الصفــة وموضوع ـ ًا لعــدم‬     ‫فضيلتكــم رد الدعــوى شــك ً‬\n      ‫وجــود أي ســب أو تطــاول والن دعــوى املدعــى ال وجاهــة لهــا شــرعا‬\n      ‫وبطلــب البينــة مــن املدعــي أجــاب لــدي صحيفة الدعــوى املقدمة لفضيلة‬\n      ‫ناظــر القضيــة واملرفقــة باملعاملــة باســم مطلقــة موكلــي ورفعــت اجللســة‬\n      ‫لالطــاع عليهــا ويف يــوم الثالثــاء املوافــق‪ 1434/10/13‬ه ـ وفيهــا حضــر‬\n      ‫الطرفــان فجــرى االطــاع علــى خطــاب مــن اربــع صفحــات وقــد ذكــرت‬\n      ‫هــذه االلفــاظ املذكــورة يف دعــوى املدعــي يف الصفحــة الثالثــة وبــدون‬\n      ‫توقيــع مــن املدعيــة او مــن احملامــي وبطلــب زيــادة بينــة أجــاب ليــس لــدي‬\n      ‫بينــة ســوى هــذا اخلطــاب وبعــرض ذلــك علــى املدعــى عليــه أجــاب ســبق‬\n      ‫ان اجبنــا عليــه يف اجللســة املاضيــة وان هــذا اخلطــاب قامــت بتوقيعــه‬\n      ‫موكلــة موكلــي وأن موكلــي مجــرد ناقــل وجهــة نظــر موكلتــه وبنــاء‬\n      ‫علــى مــا تقــدم ومــا جــاء يف دعــوى املدعــي وكالــة ومطالبتــه بتأديــب‬\n      ‫مــوكل املدعــى عليــه وحيــث ان املدعــى عليــه ال يتكلــم عــن نفســه وامنــا‬\n      ‫ناقــل وجهــة نظــر موكلتــه ولــو فتــح البــاب بتأديــب كل مــن تكلــم يف‬\n      ‫مجالــس القضــاة ومــا يصــدر مــن الفــاظ ألدى ذلــك إلى اشــغال احملاكم‬\n      ‫اجلزائيــة ومــا جــاء يف قصــة احلضرمــي والكنــدي ولقولــه تعالــى‪( :‬وال‬\n      ‫تــزر وازرة وزر أخــرى ) لــذا صرفــت النظــر عــن دعــوى املدعــي لعــدم‬\n      ‫ثبوتهــا وبعــرض احلكــم علــى املدعــي قــرر عــدم قناعتــه باحلكــم وطلــب‬\n      ‫االســتئناف وجــرى افهامــه بــأن مــده االعتــراض ثالثــن يومــا ابتــداء‬\n      ‫مــن اســتالم نســخة احلكــم وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪207‬‬\n\f‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/13‬ه ـ ويف يــوم‬\n‫الثالثــاء املوافــق‪ 1434/10/13‬ه ـ حضــر املدعــي وقــرر اســتالم نســخة‬\n‫مــن احلكــم‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34/503559‬‬\n‫وتاريــخ ‪1434/11/5‬ه املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ‪ ).....( /‬املســجل برقــم ‪ 34329653‬وتاريــخ‬\n‫‪1434/10/13‬ه ـ اخلــاص بدعــوى ‪ ).....(/‬بالوكالــة ضــد‪ ).....(/‬بشــأن‬\n‫قضيــة تلفــظ علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا باألكثريــة املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":201,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9e080fd1af16ffefa28d91f708ab3bc15a1345cfdc810ed9fdef27b1ded98315","normalized_text_hash":"dd14bd6a388458a45e279e82132d172d8cc86a877a9b7119a535efe09dd04f88","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p201-34329653"},{"id":"abcf30dd-65aa-5dd5-8721-b65d6693d0ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -تطاول املدعى عليه على املدعي -مطالبة املدعي مجازاة املدعى عليه جراء تطاوله -مصادقة املدعى عليه على الدعوى -ثبوت احلرمة والعقاب شرع ا -جلد املدعى عليه وأخذ التعهد بعدم العودة .","document_number":"33454757","case_number":"32315609","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/15","year":"1434","subject":"إيذاء الغير (حق خاص) -تطاول املدعى عليه على املدعي -مطالبة املدعي مجازاة املدعى عليه جراء تطاوله -مصادقة املدعى عليه على الدعوى -ثبوت احلرمة والعقاب شرع ا -جلد املدعى عليه وأخذ التعهد بعدم العودة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/15 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33454757 :‬‬\n                          ‫َر ْق ُم الدعوى‪32315609 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3425462‬تاريخه‪1434/01/28 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر (حــق خــاص)‪ -‬تطــاول املدعــى عليــه علــى املدعــي‪ -‬مطالبة‬\n       ‫املدعــي مجــازاة املدعــى عليــه جــراء تطاولــه‪ -‬مصادقــة املدعــى عليــه‬\n       ‫علــى الدعــوى‪ -‬ثبــوت احلرمــة والعقــاب شــرع ًا‪ -‬جلــد املدعــى عليــه‬\n                                                    ‫وأخــذ التعهــد بعــدم العــودة ‪.‬‬\n\n\n\n\n       ‫قولــه صلــى اهلل عليــه وســلم ( املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                            ‫ويــده ) ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي أن املدعــى عليــه يعمــل بإحــدى املكتبــات يف املســتودع‬\n       ‫وقــد حضــر إلــى املســتودع مــن أجــل شــراء كتــب وتفاجــأ أن املدعــى‬\n       ‫عليــه يصــرخ عليــه ويتطــاول بالــكالم وإذا به يلحــق به وزميله اآلخر إلى‬\n       ‫الســيارة وركــب الســيارة وحلــق بــه وحــاول فتــح بــاب الســيارة وركبــوا‬\n       ‫ســيارتهم وحلقــوا بــه وقامــوا بحــده وأجبــروه علــى الوقــوف بالقــوة ويطلــب‬\n       ‫مجازاتــه شــرعاً‪ -‬أنكــر املدعــى عليــه مــا جــاء بالدعــوى وقــال انــه حلــق‬\n       ‫باملدعــى عليــه بالســيارة مــن أجــل أن يطلــب حقــه فعليــه فواتيــر فوقــف‬\n       ‫مــن نفســه هكــذا أجــاب ‪ -‬ثــم جــرى االطــاع علــى القــرار الشــرعي‬\n       ‫فيمــا يتعلــق باحلــق العــام املتضمــن احلكــم بأخــذ التعهــد علــى املدعــى‬\n\n‫‪209‬‬\n\f‫عليــه ـ بنــاء علــى الدعــوى واإلجابــة ـ وحيــث صــادق املدعــى عليــه علــى‬\n‫الدعــوى وأقــر بلحاقــه للمدعــى ـ وحيــث مــا قــام بــه املدعــي عليــه فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ـ ولقولــه صلــى اهلل عليــه وســلم ( املســلم مــن‬\n‫ســلم املســلمون مــن لســانه ويــده ) ‪ -‬احلكــم بجلــد املدعــى عليــه عشــر‬\n‫جلــدات وأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا بــدر منــه ـ قــرر املدعــي‬\n‫القناعــة باحلكــم وقــرر املدعــى عليــه اعتراضــه علــى احلكــم بالئحــة‬\n‫اعتراضيــة فأفهــم بتعليمــات االســتئناف ـ صــدق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪32315609‬‬\n‫وتاريــخ ‪1432/07/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32962102‬وتاريــخ‬\n‫‪1432/07/27‬ه ـ ففــي يــوم االثنــن املوافق‪1433/11/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم وادعــى علــى احلاضــر معــه مصــري اجلنســية مبوجب‬\n‫االقامــة رقــم ‪ 209410388‬قائــا يف دعــواه يعمــل املدعــى عليــه مبكتبــة‬\n‫‪ ....‬يف املســتودع وقــد اشــتريت منــه عــدة كتــب عــن طريــق الهاتــف ويف‬\n‫يــوم ‪1431/3/15‬ه ـ حضــرت الــى املســتودع مــن اجــل شــراء كتــب‬\n‫وتفاجــأت بــه يصــرخ علــي ويتطــاول بالــكالم وخرجــت واذا بــه يلحق بي‬\n‫هــو وزميلــه إلــى الســيارة وركبــت الســيارة وحلقــوا بــي وحــاول علــي فتــح‬\n‫بــاب الســيارة وركبــوا ســيارتهم وحلقــوا بــي وقامــوا بحــدي واجبرونــي‬\n\n                                                                                          ‫‪210‬‬\n\f      ‫علــى الوقــوف بالقــوة لــذا اطلــب مجازاتــه شــرعا هــذه دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي بأنــه حضــر الــى‬\n      ‫املســتودع وأخــذ كتــاب مــن عنــدي وقــال لــي هــذا الســي دي ال يعمــل‬\n      ‫فقلــت إذا فتحتــه وعمــل ســتدفع ثمنــه قــال نعــم ففتحتــه وقمــت بتشــغيله‬\n      ‫فاشــتغل فقلــت لــه ادفــع قيمتــه فقــال ال فشــددت الــكالم معــه وبعدهــا‬\n      ‫خــرج وندمــت علــى الــذي حصــل وحلقــت بــه مــن أجــل أن اعتــذر وحلقــت بــه‬\n      ‫بالســيارة مــن اجــل ان اطلــب حقــي فعليــه فواتيــر فوقــف مــن نفســه هــذه‬\n      ‫إجابتــي هــذا وقــد جــرى االطــاع علــى القــرار الشــرعي رقــم ‪/4/308‬ج‬\n      ‫وتاريــخ ‪1431/06/26‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫اجلزئيــة ســابقا ‪ .........‬مبــا يتعلــق باحلــق العــام بأخــذ التعهــد علــى املدعــى‬\n      ‫عليــه فبنــاء علــى الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث صــادق‬\n      ‫املدعــى عليــه الدعــوى واقــر بلحاقــه للمدعــي وحيــث مــا قــام بــه املدعــي‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا ولقولــه صلــى اهلل عليــه وســلم «‬\n      ‫املســلم مــن ســلم املســلمون مــن لســانه ويــده « ولــكل مــا تقــدم فقــد‬\n      ‫حكمــت بجلــد املدعــى عليــه عشــر جلــدات واخــذ التعهــد عليــه بعــدم‬\n      ‫العــودة ملثــل مــا بــدر منــه وبذلــك حكمــت وبعــرض ذلــك علــى الطرفــن‬\n      ‫قــرر املدعــي القناعــة وقــرر املدعــى عليــه عــدم القناعــة واســتعد بتقــدمي‬\n      ‫الئحــة اعتراضيــة علــى احلكــم فأفهــم بــأن مــدة اإلعتــراض ثالثــون‬\n      ‫يومــا مــن تاريــخ احلكــم يف هــذا اليــوم اإلثنــن ‪1433/11/15‬ه ـ وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                 ‫يف ‪ 1433/11/15‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n      ‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n\n\n‫‪211‬‬\n\f‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بجــدة املســاعد رقــم ‪ 32/962102‬وتاريــخ‬\n‫‪1433/11/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫القاضــي باحملكمــة اجلزائيــة بجــدة رقــم ‪ 33454757‬وتاريــخ‬\n‫‪1433/11/15‬ه ـ احملكــوم فيــه مبــا دون بباطــن الصــك املتضمــن‬\n‫دعــوى ســعودي اجلنســية ضــد‪ /‬مصــري اجلنســية يف اعتــداء وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                          ‫وصحبــه وســلم‬\n\n\n\n\n                                                                           ‫‪212‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":209,"source_page_end":212,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0630634c8b6e369fd60cd490d4ffb1daa44b23485fe7da415feff53f7c936a44","normalized_text_hash":"e2bfd2706075ea83182992e39f661bb53271ed072f49738d8b2b79be7217872f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p209-33454757"},{"id":"ce84f269-de1f-583c-8081-ee2d1c0a0457","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتلفظ -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -شهادة الشاهدين بالواقعة- منشأ الدعوى ألفاظ املدعى عليه -إيجابية التقرير الطبي -إدانة","document_number":"34233705","case_number":"32452925","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتلفظ -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -شهادة الشاهدين بالواقعة- منشأ الدعوى ألفاظ املدعى عليه -إيجابية التقرير الطبي -إدانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/6/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34233705 :‬‬\n                         ‫َر ْق ُم الدعوى‪32452925 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34343097‬تاريخه‪1434/10 /28 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتلفــظ‪ -‬مطالبــة املدعــي‬\n      ‫باملجــازاة‪ -‬إنــكار املدعــى عليــه الدعــوى‪ -‬شــهادة الشــاهدين بالواقعــة‪-‬‬\n      ‫منشــأ الدعــوى ألفــاظ املدعــى عليــه ‪ -‬إيجابيــة التقريــر الطبــي ‪ -‬إدانــة‬\n                                                                      ‫املدعــى عليــه ‪.‬‬\n\n\n\n\n                                                      ‫اإلقرار حجة شرعية على املقر‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه احلاضــر معــه قــام بالتلفظ عليــه بألفاظ‬\n      ‫بذيئــة ثــم تشــابك معــه باأليــدي وضربــه بيــده وبعقــال ممــا تســبب يف‬\n      ‫إصابتــه بجــروح يف أنفــه ويــده وقدمــه‪ ،‬ولــذا فقــد طلــب احلكــم عليــه‬\n      ‫بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه تلفظــه علــى املدعــي‬\n      ‫وأقــر بحصــول ســوء تفاهــم بينهمــا أدى إلــى متاســك باأليــدي‪ -‬أحضــر‬\n      ‫املدعــي شــاهدين شــهدا مبــا يثبــت دعــواه وجــرى تعديلهمــا شــرعاً‪-‬‬\n      ‫املدعــى عليــه هــو مــن تســبب يف نشــوب هــذه املضاربــة بتلفظــه علــى‬\n      ‫املدعــي كمــا أنــه تســبب يف إصابتــه بجــرح مــدة شــفاءه املتوقعــة ثالثــة‬\n      ‫أيــام حســب التقريــر الطبــي‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا‬\n      ‫نســب إليــه وقــررت ســجنه ملــدة ثالثــة أيــام وأخــذ التعهــد عليــه بعــدم‬\n\n‫‪213‬‬\n\f‫العــودة ملــا بــدر منــه‪ -‬عــارض املدعــي واملدعــى عليــه علــى احلكــم‪-‬‬\n               ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫اجلزئيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ...../‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئية يف محافظة االحساء برقم ‪ 32452925‬وتاريخ ‪1432/10/15‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 321286953‬وتاريــخ ‪ 1432/10/15‬هـ حضر‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ) وادعــى علــى احلاضــر‬\n‫ا إننــي أعمــل‬  ‫معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم( ) قائـ ً‬\n‫وكيــل مدرســة مبتوســطة ‪ .........‬ب ـ ‪ .................‬ويف يــوم اإلثنــن املوافــق‬\n‫دخلت لغرفة املدرســن ألقوم بتكليف بعض املدرســن‬                   ‫ُ‬      ‫‪1432/6/26‬هـ‬\n‫يف احلصــص التــي ال يوجــد بهــا معلــم فقــال لــي األســتاذ هــذا احلاضــر‬\n‫معــي أريــد أن أطبــع أســئلة االختبــار عنــدك فقلـ ُـت لــه أخشــى أن يختــرب‬\n‫جهــازي ألن الفالشــات يوجــد بهــا فيروســات وليــس مــن عملــي طباعــة‬\n‫أســئلة املدرســن فقــال لــي أريــد الطابعــة فقــط فقلـ ُـت لــه قــد تكــون‬\n‫الطابعــة غيــر متعرفــة علــى جهــازك فقــال لــي (حقتــك حلــوة متعرفــة‬\n‫ـككت مــاذا يقصــد بهــذه العبــارة وقلـ ُـت لــه أنــت‬  ‫ُ‬          ‫علــى كل أحــد) فشـ‬\n‫فقلت‬\n ‫ُ‬      ‫رجــل كبيــر ال تتكلــم بهــذا الــكالم فقــال لــي الشــيب وال العيــب‬\n‫لــه أنــت لســت بكبيــر وال أديــب فقــال لــي مــا عليــك زود منكــم نســتفيد‬\n‫فضحــك املعلمــون احلاضريــن بالغرفــة فخرجـ ُـت ألداء عملــي ويف اليــوم‬\n‫التالــي وهــو يــوم الثالثــاء املوافــق ‪1432/6/27‬ه ـ دخــل املدعــي عليــه‬\n‫مكتبــي ومعــي املرشــد الطالبــي وبعــض الطــاب وكان يحمــل معــه‬\n\n                                                                                          ‫‪214‬‬\n\f      ‫حاســبه اآللــي والفــاش ميمــوري وطلــب طباعــة أســئلة االختبــار وألنهــا‬\n      ‫ســرية ومكتبــي بــه عــدد كبيــر مــن الطــاب فطلبـ ُـت منــه مرافقتي إلى‬\n      ‫املكتــب املجــاور لكــي يقــوم بطباعــة أســئلة االختبــار فلمــا دخلـ ُـت وإيــاه‬\n      ‫للمكتــب وحفاظ ـ ًا علــى ســرية األســئلة قمـ ُـت بإغــاق البــاب ثــم قلـ ُـت‬\n      ‫لــه يــا أســتاذ الــكالم البــذيء ال تتكلــم بــه مــرة أخــرى فنهرنــي وقــال‬\n      ‫أبعــد عنــي فدفعنــي ودفعتــه ثــم ضربنــي بعقالــه وضربتــه بــه ثــم ضربنــي‬\n      ‫علــى أنفــي وكان يف إصبــع يــده التــي ضربنــي بهــا خــامت كبيــر فصــه‬\n      ‫وضربنــي بــه علــى أنفــي وأدمانــي فتدافعـ ُـت وإيــاه ودفعنــي علــى زجــاج‬\n      ‫مرمــي علــى األرض فاجنرحــت قدمــي وتضاربـ ُـت أنــا وإيــاه ودفعنــي‬\n      ‫علــى اجلــدار ثــم التفــت وأخــذ مثلــث بالســتيكي يســتعمله مــدرس‬\n      ‫ـكت وإيــاه فانكســر املثلــث بيننــا فاجنرحــت يــدي‬        ‫الرياضيــات فتماسـ ُ‬\n      ‫اليســرى ومــن شــدة الســحب بينــي وبينــه جــرح رأســه ببقايــا املثلــث‬\n      ‫الــذي يف يــده ثــم دفعنــي وقــال لــي خــاص يــا شــيخ فتوقفـ ُـت وإيــاه‬\n      ‫عــن املضاربــة واتصــل علــى أحــد األســاتذة وقــد حضــر مديــر املدرســة‬\n      ‫وبعــض املدرســن وفتحـ ُـت بــاب املكتــب وقــد حــاول املديــر واحلاضريــن‬\n      ‫حــل املشــكلة لكــن دون فائــدة ومت ذهــاب كل واحــد منــا للمستشــفى‬\n      ‫أطلــب مجازاتــه لقــاء مــا بــدر منــه‪ ،‬وبعــرض الدعــوى علــى املدعــى عليــه‬\n      ‫ا ال صحــة ملــا ذكــره املدعــي يف دعــواه والصحيــح إننــي‬           ‫أجــاب قائ ـ ً‬\n      ‫أعمــل مــدرس رياضيــات مبتوســطة ‪ .........‬ب ـ ‪ .................‬ويف يــوم اإلثنــن‬\n      ‫املوافــق ‪1432/6/26‬ه ـ دخــل علينــا يف غرفــة املدرســن وكيل املدرســة‬\n      ‫هــذا احلاضــر معــي فطلبـ ُـت منــه طابعــة جهــازه احلاســب اآللــي ألمتكــن‬\n      ‫مــن طباعــة أســئلة االختبــار فقــال لــي إن طابعــة جهــازي قــد ال تتعــرف‬\n      ‫علــى كمبيوتــرك فقلـ ُـت لــه طابعتــك تتعــرف علــى أي جهــاز فقــال لــي‬\n\n\n‫‪215‬‬\n\f‫يالشــايب يالعايــب فقلـ ُـت لــه الشــيب وال العيــب فقــال لــي أنــت العيــب‬\n‫كلــه فقلـ ُـت لــه ومنــك نســتفيد ثــم انصــرف كل منــا يف حــال ســبيله‬\n‫ـرت‬‫ويف اليــوم التالــي وهــو يــوم الثالثــاء املوافــق ‪1432/6/27‬ه ـ حضـ ُ‬\n‫ملكتــب املدعــى عليــه ومعــي جهــاز احلاســب اآللــي وفــاش ميمــوري بهــا‬\n‫أســئلة االختبــار وطلبـ ُـت مــن املدعــى عليــه متكينــي مــن طباعــة األســئلة‬\n‫دخلت‬\n ‫ُ‬        ‫فطلــب منــي مرافقتــه إلــى مكتــب اإلدارة ولــم يكــن بــه أحــد وملــا‬\n‫معــه مكتــب اإلدارة أغلــق البــاب علينــا وأخــذ يتكلــم علـ ّـي بألفــاظ‬\n‫بذيئــة ويســبني ويشــتمني وأخــذ العقــال مــن رأســي وضربنــي بــه وأنــا‬\n‫أحــول تهدئتــه ولكــن دون فائــدة وأخــذ مثلــث بالســتيكي وضربنــي بــه‬\n‫علــى رأســي ممــا أدى إلــى إصابتــي وقــام بضربــي علــى اجلــدار فاتصلـ ُـت‬\n‫بأحــد املعلمــن بعــد أن ســقط علــى األرض وطلبـ ُـت مــن أحــد املعلمــن أن‬\n‫يحضــر إلينــا ليبعــده عنــي ثــم حضــر املديــر وبعــض املدرســن وطرقــوا‬\n‫البــاب عليــه حتــى فتــح البــاب ثــم ملــا دخلــوا علينــا أخــذ يســبني ويشــتمني‬\n‫ثــم مت أخــذي ملستشــفى احلــرس وهنــاك تلقيـ ُـت العــاج فليــس لــه حــق‬\n‫عنــدي بــل احلــق لــي عليــه وتوجــد لديكــم دعــوى لــي ضــده أطلــب بحقــي‬\n‫منــه يف اعتدائــه علـ ّـي وبــرد تلــك اإلجابــة علــى املدعــي قــال ال صحــه ملــا‬\n‫ذكــره املدعــى عليــه يف اجابتــه والصحيــح هــو مــا ذكرتــه يف دعــواي‬\n‫ولــدي بينــه واحضــر املدعــي للشــهادة كل مــن الســعودي بالســجل‬\n‫املدنــي برقــم ( ) والســعودي بالســجل املدنــي برقــم( ) وبســؤالهما عمــا‬\n‫لديهمــا مــن الشــهادة شــهد قائــا أشــهد بــاهلل العظيــم أنــه يف أحــد‬\n‫األيــام وبينمــا كنــت برفقــة املديــر أبلغنــا بوجــود مشــكلة بــن األســتاذ‬\n‫والوكيــل وعنــد ذهابنــا لهمــا وفتــح الغرفــة التــي كانــا فيهــا وجدناهمــا‬\n‫قــد تضاربــا مــع بعضهمــا والدمــاء تســيل منهمــا وحاولنــا الصلــح بينهمــا‬\n\n\n                                                                                        ‫‪216‬‬\n\f      ‫فطلبــا تأجيــل املوضــوع وقــد ذهــب برفقة للمستشــفى كمــا ذهب برفقة‬\n      ‫للمستشــفى وقمنــا بالتحقيــق يف املوضــوع مــع كل منهــم وســألناهم عــن‬\n      ‫أســباب تلــك املضاربــة فأفادونــا أنــه يف اليــوم الــذي قبــل املضاربــة ذهــب‬\n      ‫األســتاذ وهــو وكيــل شــئون الطــاب لغرفــة املدرســن إن لــدي فــاش‬\n      ‫ميمــوري وأرغــب اســتعمال الطابعــة التــي لديــك فقــال لــه األســتاذ رمبــا‬\n      ‫الطابعــة ال تتعــرف علــى الفــاش ميمــوري الــذي لديــك فقــال لــه حقتــك‬\n      ‫حلــوة وتتعــرف علــى كل شــيء فــرد عليــه األســتاذ الشــيب وال العيــب‬\n      ‫ا ومنكــم نســتفيد‬     ‫فقــال لــه األســتاذ أنــت العيــب كلــه فــرد عليــه قائـ ً‬\n      ‫ـدي مــن الشــهادة علمـ ًا بأننــي اعمــل وكيــل الشــئون اإلداريــة‬   ‫هــذا مــا لـ ّ‬\n      ‫ا لشــئون الطــاب واالســتاذ معلــم‬     ‫مبدرســة ‪ .................‬واالســتاذ وكيـ ً‬\n      ‫ا أشــهد بــاهلل العظيــم أنــه بعــد حصــول‬       ‫باملدرســة كمــا شــهد قائ ـ ً‬\n      ‫املضاربــة جــرى التحقيــق يف موضــوع املضاربــة بــن االســتاذ واالســتاذ مع‬\n      ‫االســاتذة كل مــن شــرف اخللــف وســؤالهم عــن أســباب تلــك املضاربــة‬\n      ‫فأفــادوا بــأن األســتاذ قــد دخــل غرفــة املدرســن وطلــب منــه االســتاذ‬\n      ‫ا إننــي أرغــب يف اســتعمال الطابعــة التــي لديــك فقــال لــه األســتاذ‬      ‫قائ ـ ً‬\n      ‫رمبــا الطابعــة ال تتعــرف علــى الفــاش ميمــوري الــذي لديــك فقــال لــه‬\n      ‫حقتــك حلــوة وتتعــرف علــى كل شــيء فقــال لــه االســتاذ وعايــب فــرد‬\n      ‫عليــه االســتاذ وال العيــب فقــال لــه االســتاذ انــت العيــب كلــه فــرد عليــه‬\n      ‫ـدي مــن الشــهادة علم ـ ًا بأننــي أعمــل‬\n                                               ‫ا ومنكــم نســتفيد هــذا مــا لـ ّ‬      ‫قائ ـ ً‬\n      ‫مرشــد طالبــي باملدرســة وبعــرض شــهادة الشــاهدين علــى املدعــى‬\n      ‫ا إن مــا جــاء يف شــهادة الشــاهدين علـ ّـي غيــر صحيــح‬      ‫عليــه أجــاب قائ ـ ً‬\n      ‫ـدي علــم إال أن املديــر هــو مــن قــام بالتحقيــق يف ذلــك املوضــوع‬  ‫وليــس لـ ّ‬\n      ‫فالشــاهدين لــم يكونــا موجديــن يف التحقيــق كمــا أن األســتاذ مــع‬\n\n\n‫‪217‬‬\n\f‫دخولــه هــو واملديــر يف تلــك الغرفــة التــي حصلــت فيهــا املشــكلة قــام‬\n‫املدعــي بســبي بقولــه لــي يــا حمــار كمــا أن مكتــب املدعــي الليلــي‬\n‫لــم يكــن مركــز لتصويــر األســئلة والتصويــر كان يف مكتــب املديــر‬\n‫النهــاري وبســؤال الشــاهدين عمــا ذكــره املدعــى عليــه أجــاب الشــاهد‬\n‫ا إن التحقيــق قــد حصــل مــن قبــل جلنــة مكونــة مــن ثالثــة أشــخاص‬       ‫قائـ ً‬\n‫أنــا أحدهــم ومديــر املدرســة واألســتاذ كمــا أن املدعــي لــم يقــل للمدعــى‬\n‫عليــه يــا حمــار وإمنــا أثنــاء دخولنــا وقــت املضاربــة علــى املدعــي واملدعــى‬\n‫عليــه ســمعنا املدعــي يقــول للمدعــى عليــه إن هــذا الــكالم ال يصــدر إال‬\n‫مــن احلمــارة ويقصــد بذلــك الكلمــة التــي قالهــا لــه املدعــى عليــه وهــي‬\n‫(حقتــك حلــوة تتعــرف علــى كل شــيء) كمــا أنــه مســموح التصويــر يف‬\n‫ا إن التحقيــق قــد حصــل‬     ‫املكتــب النهــاري أو الليلــي كمــا أجــاب قائـ ً‬\n‫مــن قبــل جلنــة مكونــة مــن ثالثــة أشــخاص أنــا أحدهــم ومديــر املدرســة‬\n‫ووكيــل املدرســة ا ٍألســتاذ كمــا أنــه مســموح التصويــر يف املكتــب‬\n‫ال مــن‬\n      ‫النهــاري أو الليلــي كمــا أحضــر املدعــي لتزكيــة الشــاهدين ك ً‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ) ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬وأضــاف املدعــي قائــا أود أن أوضــح‬\n‫لفضيلتكــم بأننــي إمــام مســجد منــذ خمــس عشــرة ســنه وأنــا اآلن إمــام‬\n‫مســجد ‪ .........................‬منــذ عــام ‪1417‬ه ـ كمــا أننــي مــدرس دراســات‬\n‫إســامية منــذ ثــاث عشــره ســنه وقبلهــا كنــت إمــام وواعــظ بالشــؤون‬\n‫الدينيــة باحلــرس الوطنــي منــذ عــام ‪1409‬ه ـ وأنــا حافــظ لكتــاب اهلل‬\n‫واهلل احلمــد واملنــة منــذ عــام ‪1412‬ه ـ كمــا أننــي تخرجــت مــن معهــد‬\n‫احلــرم املكــي عــام ‪1417‬ه ـ ومتخــرج مــن قســم الشــريعة بكليــة‬\n‫الشــريعة باإلحســاء عــام ‪1421‬ه ـ ولــي اآلن دروس ومحاضــرات بســجن‬\n\n\n                                                                                        ‫‪218‬‬\n\f      ‫اإلحســاء وكان حاضــرا املدعــي العــام فجــرى عــرض هــذه الدعــوى‬\n      ‫عليــه فقــال إننــي ال أرغــب يف إقامــة دعــوى عامــة علــى املدعــى عليــه‬\n      ‫يف الوقــت احلالــي ألننــي غيــر مخــول مــن مرجعــي لــذا وبعــد ســماع‬\n      ‫الدعــوى واإلجابــة وحيــث طلــب املدعــي مجــازاة املدعــى عليــه لتلفظــه‬\n      ‫عليــه واعتدائــه بالضــرب والتســبب يف إصابتــه وإن املدعــى عليــه قــد‬\n      ‫أقــر بحصــول ســوء تفاهــم بينهمــا أدى ذلــك إلــى التماســك باأليــدي وإن‬\n      ‫اإلقــرار حجــة شــرعية علــى املقــر وإن املتأمــل لهــذه القضيــة يجــد أن‬\n      ‫منشــأها هــو مــا تلفــظ بــه املدعــى عليــه علــى املدعــي وإن البينــة املوصلــة‬\n      ‫واملعدلــة التعديــل الشــرعي قــد أثبتــت ذلــك وإن مــدة شــفاء املدعــي قــد‬\n      ‫حــددت مــن يومــن إلــى ثالثــة أيــام وذلك حســبما أوضحــه التقرير الطبي‬\n      ‫الصــادر مــن مستشــفى امللــك عبدالعزيــز باحلــرس الوطنــي باألحســاء‬\n      ‫برقــم (‪ )53525‬تاريــخ ‪2011/11/22‬م وإنــه ال ســوابق علــى املدعــى‬\n      ‫عليــه وحيــث إن للمدعــى عليــه هنــا دعــوى ضــد املدعــي يف هــذه القضيــة‬\n      ‫يطالــب مبجازاتــه العتدائــه عليــه بالضــرب وقــد حكــم علــى املدعــى‬\n      ‫عليــه يف جلســتها التــي قبــل هــذه اجللســة مباشــرة لــذا فقــد تقــرر مــا‬\n      ‫يلــي أوال ثبــوت إدانــة املدعــى عليــه لتلفظــه علــى املدعــي واعتدائــه عليــه‬\n      ‫بالضــرب وتعزيــره لقــاء ذلــك بســجنه ثالثــة أيــام تبــدأ مــن تاريــخ إيقافــه‬\n      ‫بســبب هــذه القضيــة ال ينفــذ ذلــك الســجن إال بحضــور املدعــي ويســقط‬\n      ‫بإســقاطه أو بعضــه ثانيــا أخــذ التعهــد الــازم عليــه بعــدم العــودة ملثــل‬\n      ‫مــا بــدر منــه مســتقبال وبذلــك كلــه حكمــت يف احلــق اخلــاص وبعرضــه‬\n      ‫اعتــرض عليــه املدعــي واملدعــى عليــه وكالــه وطلبــا تقــدمي الئحــة‬\n      ‫اعتراضيــة فجــرى إفهامهمــا بأنــه ســوف يتــم تســليمه صــورة مــن القــرار‬\n      ‫الشــرعي يــوم غــدا األربعــاء ‪1434/6/7‬ه ـ وإن لهمــا مــدة ثالثــن يوم ـ ًا‬\n\n\n‫‪219‬‬\n\f‫تبــدأ مــن تاريــخ اســتالمهما بعدهــا يســقط حقهمــا يف تقــدمي الالئحــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/6/6‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/08/28‬ه ـ حيــث‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية واملتعلقــة‬\n‫بدعــوى ضــد وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة‬\n‫األولــى رقــم (‪ )34288614‬تاريــخ ‪14324/8/6‬ه ـ املتضمــن أوال‬\n‫فضيلتــه أشــار إلــى وجــود حكــم علــى املدعــي يف دعــوى أقامهــا املدعــى‬\n‫عليــه ولــم جنــد أن فضيلتــه أطلــع علــى هــذا الصــك وأرفــق صــورة منــه‬\n‫ثانيــا املدعــى عليــه اعتــرض علــى احلكــم ولــم جنــد أن فضيلتــه ســلم‬\n‫لــه صــورة مــن القــرار وقــد احلــق يف صــورة الضبــط انــه قــدم الئحــة‬\n‫اعتراضيــة يف ‪1434/7/22‬ه ـ مــع انــه لــم يســلم لــه صــورة مــن احلكــم‬\n‫ثالثــا املدعــي جــرى تســليمه صــورة مــن القــرار ولــم يكمــل الــازم بعــد‬\n‫ذلــك رابعــا فضيلتــه اثبــت إدانــة املدعــى عليــه بالضــرب للمدعــي فهــل‬\n‫ذلــك مــن املدعــى عليــه ابتــدأ أم دفاعــا ولوجاهــة مــا ارتــأوه أصحــاب‬\n‫الفضيلــة فأجيــب أوال بالنســبة للمالحظــة األولــى جتــدون صــورة مــن‬\n‫القــرار املصــدق عليــه مــن قبــل قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية فيمــا يتعلــق بدعــوى املدعــي عليــه هنــا‬\n‫ضــد املدعــي أمــا بالنســبة للمالحظــة الثانيــة والثالثــة فقــد مت تســليم‬\n‫املدعــى عليــه واملدعــي صــورة مــن القــرار حيــث إن كال منهمــا قــدم‬\n‫الئحتــه االعتراضيــة إال أن الكاتــب لــم يثبــت ذلــك يف الضبــط حســب‬\n‫املتبــع وهــذا ســهوا منــه وســوف يتــم تــدارك مثــل هــذا مســتقبال إن شــاء‬\n‫اهلل تعالــى أمــا املالحظــة الرابعــة فــإن هــذه القضيــة مضاربــة وقعــت بــن‬\n\n\n                                                                                    ‫‪220‬‬\n\f      ‫املدعــى عليــه واملدعــي ومثــل هــذه القضايــا يصعــب حتديــد املبتــدئ‬\n      ‫بتلــك املضاربــة حيــث إنــه يدعــي كل منهمــا ان صاحبــه هــو مــن ابتــدأ‬\n      ‫بتلــك املضاربــة ولــذا فقــد نظرنــا قضيتــن يف هــذه املضاربــة أحدهمــا يف‬\n      ‫القضيــة األولــى مــدع ويف القضيــة الثانيــة مدعــى عليــه واآلخــر مثلــه وقد‬\n      ‫صدقــت القضيــة األولــى حســبما يتضــح ألصحــاب الفضيلــة مــن صــورة‬\n      ‫الصــك املرفــق وهــذه هــي القضيــة الثانيــة لــذا فاإلجــراء مــا تقــدم وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                ‫حــرر يف ‪1434/8/28‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنا نحن قضــاة الدائرة اجلزائية األولى‬\n      ‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف الشــيخ‬\n      ‫د‪ ................ .‬برقــم ‪ 1747050/34‬وتاريــخ ‪1434/9/3‬ه املقيــدة لــدى‬\n      ‫احملكمــة برقــم ‪ 342159721‬وتاريــخ ‪1434/9/10‬ه املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلتــه املســجل برقــم ‪ 34233705‬وتاريــخ ‪1434/6/7‬ه‬\n      ‫اخلــاص بدعــوى‪ ............... /‬ضــد‪ ................. /‬يف قضيــة شــتم وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬حيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه والالئحتــن االعتراضيتــن وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم ‪ 34288614‬يف ‪1434/8/6‬ه قررنــا املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                             ‫حــرر يف ‪1434/10/25‬هــ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":213,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ec54786da93cdf2bdc049f0fa9864e996619f5736d156dbc78c8205185a07c9b","normalized_text_hash":"af2ae85d81c0b18f33b8605c9998e38ec6cbc35e4452d515387867ef388d5eed","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p213-34233705"},{"id":"fd862150-021f-5e60-904a-6c3278eed37b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -باغ كيدي تسبب يف السجن -مطالبة املدعي بتعزير املدعى عليه -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"33361564","case_number":"32597663","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة 222 على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/29","year":"1434","subject":"إيذاء الغير (حق خاص) -باغ كيدي تسبب يف السجن -مطالبة املدعي بتعزير املدعى عليه -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33361564 :‬‬\n                   ‫َر ْق ُم الدعوى‪32597663 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 33428858‬تاريخه‪1433/10/17 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬بــاغ كيــدي تســبب يف الســجن‪ -‬مطالبــة‬\n‫املدعــي بتعزيــر املدعــى عليــه‪ -‬بينــة املدعــي غيــر موصلــة‪ -‬ميــن املدعــى‬\n                                  ‫عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n    ‫قول النبي صلى اهلل عليه وسلم‪( :‬ولكن اليمني على املدعى عليه)‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه قــدم ضــده بالغــا ملركــز الشــرطة بأنــه‬\n‫أشــهر الســاح يف وجهــه فتــم إيقافــه علــى إثــر ذلــك ملــدة يــوم واحــد إال‬\n‫أن املدعــى عليــه لــم يتمكــن مــن إثبــات ذلــك ضــده‪ ،‬ولــذا فقــد طلــب‬\n‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه بأنــه قــدم‬\n‫بالغــا ضــد املدعــي ودفــع بأنــه فعــل ذلــك بســبب تهديــده لــه وألختــه‬\n‫وقيامــه بضربهــا‪ ،‬كمــا أنكــر أن يكــون ذلــك البــاغ هــو الســبب يف‬\n‫توقيفــه‪ -‬اطلعــت احملكمــة علــى ملــف القضيــة فلــم جتــد فيــه مــا يثبــت‬\n‫دعــوى املدعــي‪ -‬طلــب املدعــي ميــن خصمــه علــى نفــي دعــواه فأداهــا‬\n‫طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعــي جتــاه املدعــى عليــه لعــدم ثبــوت موجبهــا‪ -‬قنــع املدعــى عليــه‬\n‫باحلكــم وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n\n                                                                                     ‫‪222‬‬\n\f                                                                        ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ .‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائية يف محافظة االحساء برقم ‪ 32597663‬وتاريخ ‪1432/12/23‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 321610827‬وتاريــخ ‪1432/12/23‬ه ـ ففــي‬\n      ‫هــذا اليــوم الســبت املوافق‪1433/02/27‬ه ـ فتحــت اجللســة الســاعة‬\n      ‫‪ 11 :00‬وفيهــا حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..........‬وادعــى علــى الغائــب عــن اجللســة قائــا لقــد ســبق أن تقــدم‬\n      ‫عــن اجللســة ببــاغ ضــدي بأننــي أشــهرت الســاح يف وجهــه ولــم يثبــت‬\n      ‫ذلــك وقــد ترتــب علــى ذلــك ســجني مبركــز شــرطة الصاحليــة ملــده يــوم‬\n      ‫واســائه لســمعتي اطلــب مجازاتــه لقــاء ذلــك ولعــدم حضــور املدعــى عليــه‬\n      ‫جــرى تأجيــل اجللســة ويف يــوم االثنــن املوافق‪1433/05/10‬ه ـ حضــر‬\n      ‫املدعــي واملدعــى عليــه ‪ ...........‬ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫‪ ..........‬وبعــرض دعــوى املدعــي علــى املدعــى عليــه أجــاب قائــا ال صحــه‬\n      ‫ملــا ذكــره املدعــي يف دعــواه والصحيــح أن املدعــي هــو شــقيقي األكبــر‬\n      ‫وتوجــد بينــي وبينــه قضايــا كثيــره يف هــذه احملكمــة لــدى أربعــة‬\n      ‫مكاتــب قضائيــة وأمــا القضيــة التــي يذكرهــا يف دعــواه إنــه حصــل‬\n      ‫ســوء تفاهــم بينــي وبينــه قــام علــى أثــره بتهديــدي بأنــه ســوف يطلــق علــي‬\n      ‫وعلــى أختــي ‪ ......‬وإنــه قــام بضربهــا ضربــا مبرحا وألنه يعمــل بالدوريات‬\n      ‫األمنيــة فتقدمــت بشــكوى ضــده ملركــز شــرطة الصاحليــة وملــا ســألني‬\n      ‫احملقــق هــل رأيــت ســاح بيــد املدعــي عندمــا هــددك فقلــت إننــي رأيــت‬\n\n‫‪223‬‬\n\f‫شــيئا أســود يف يــده وال أعلــم مــا هــو لكننــي ظننتــه مســدس ألنــه قــال‬\n‫ســيطلق علــي وعلــى اختــي ‪ ......‬ويقتلنــا ثــم ملــا نصحنــي احملقــق تنازلــت‬\n‫عنــه يف تلــك الليلــة لكنــه ســجن ألنه ضرب اختي ضربــا مبرحا واتهمته‬\n‫بأنــه اخــذ منهــا اغراضــا فســجنه ليــس ألننــي اتهمتــه بأنــه اشــهر ســاح‬\n‫علــي وإمنــا بســبب ضربــه ألختــي واتهامهــا لــه لــذا فليــس لــه حــق عنــدي‬\n‫وبــرد ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه يف دعــواي وامــل مــن‬\n‫فضيلتكــم الكتابــة لشــرطة الصاحليــة ألفادتكــم عــن صحــة ذلــك لــذا‬\n‫وحيــث االمــر مــا ذكــر فقــد امرنــا بالكتابة لشــرطة الصاحليــة ألفادتنا‬\n‫مبــا لديهــم يف هــذه القضيــة وتزويدنــا بصــوره مــن ملــف القضيــة وجــرى‬\n‫تأجيــل اجللســة ويف يــوم الثالثــاء املوافــق ‪1433/7/29‬ه ـ حضــر املدعــي‬\n‫واملدعى عليه وكان ســبق أن كتبنا ملركز شــرطة الصاحلية بخطابنا‬\n‫رقــم ‪ 33/881207‬وتاريــخ ‪1433/5/18‬ه وخطابنــا رقــم ‪33/989029‬‬\n‫وتاريــخ ‪1433/6/2‬ه ـ إلفادتنــا عــن صحــة مــا ذكــره املدعــي مــن إن‬\n‫املدعــى عليــه قــد تســبب يف ســجنه بســبب اتهامــه للمدعــي بأنــه قــد‬\n‫هــدده مبســدس وإفادتنــا كــم مــدة ســجنه والســبب يف ســجنه فوردنــا‬\n‫خطاب مدير شــرطة محافظة االحســاء برقم ‪/9/21‬ص‪ 4240/‬وتاريخ‬\n‫‪1433/6/4‬ه ـ ونــص احلاجــة منــه ( عليــه نفيدكــم بــأن املذكــور قــد مت‬\n‫إيقافــه لدينــا علــى ذمــة قضيــة مضاربــه بتاريــخ ‪1431/10/4‬ه ـ وأفــرج‬\n‫عنــه بتاريــخ ‪1433/10/5‬ه ـ وصــدر بحقــه يف القضيــة القــرار الشــرعي‬\n‫رقــم ‪ 4/119‬يف ‪1432/7/2‬ه ـ املتضمــن تعزيــره بالســجن خمســة أيــام‬\n‫وجلــده ثالثــن جلــدة ومت إنفــاذ املقــرر شــرعا ) أ ‪ .‬ه ـ وبعــرض ذلــك علــى‬\n‫املدعــي واملدعــى عليــه قــررا قناعتهمــا مبــا جــاء فيــه وقــال املدعــي إننــي‬\n‫اطلــب مــن املدعــى عليــه إن يحلــف بــاهلل العظيــم بأنــه لــم يتســبب يف‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫ســجني فــإن هــو حلــف فــا أطالبــه بشــيء بخصــوص هــذه الدعــوى‬\n      ‫وبعــرض ذلــك علــى املدعــى عليه اســتعد بــأداء اليمني وأداهــا قائال واهلل‬\n      ‫العظيــم إننــي لــم أتســبب يف ســجن أخــي هــذا احلاضــر معــي وإمنــا تســبب‬\n      ‫يف ســجنه هــو لضربــه شــقيقتي وقــد جــرى منــا مناصحــة الطرفــن ملــا‬\n      ‫بينهمــا مــن قرابــة ولكــن املدعــي أصــر علــى مجــازات املدعــى عليــه‬\n      ‫لــذا وبعــد ســماع الدعــوى واإلجابــة وان املدعــى عليــه قــد أنكــر ذلــك‬\n      ‫وذكــر بــان الســبب يف ســجنه هــو العتدائــه علــى أختــه وليــس بســببه‬\n      ‫وإن مركــز الشــرطة املختــص قــد ذكــر بــأن الســبب يف ســجن املدعــي‬\n      ‫هــو العتدائــه علــى أختــه وليــس بســبب اتهــام املدعــى عليــه للمدعــي وإن‬\n      ‫املدعــي قــد طلــب ميــن خصمــه علــى نفــي دعــواه وإن املدعــى عليــه قــد‬\n      ‫اســتعد بــأداء وإن املدعــى عليــه قــد اســتعد بــأداء اليمــن وأداهــا ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم ( ولكــن اليمــن علــى املدعــى عليــه ) وملــا هــو‬\n      ‫مقــرر شــرعا بــأن اليمــن تقطــع اخلصومــة يف احلــال لــذا فقــد حكمــت‬\n      ‫بصــرف النظــر عــن طلــب املدعــي يف مجــازات املدعــى عليــه لعــدم ثبــوت‬\n      ‫موجبــه وبعرضــه قــرر املدعــى عليــه قناعتــه بــه أمــا املدعــي فاعتــرض‬\n      ‫عليــه وطلــب تقــدمي الئحــة اعتراضيــه فأفهمنــاه بــأن لــه مــدة شــهر تبــدأ‬\n      ‫مــن تاريــخ اليــوم وبعدهــا يســقط حقــه يف تقــدمي الئحــة اعتراضيــه‬\n      ‫ويكتســب احلكــم القطعيــة ففهــم ذلــك بحضــور وشــهادة كال مــن‬\n      ‫جنــدي احملكمــة وموظــف املكتــب وأقفلــت اجللســة الســاعة العاشــرة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‬\n                                                            ‫حــرر يف ‪1433/7/29‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ‬\n      ‫وكانــت قــد وردتنــا املعاملــة مــن محكمة االســتئناف باملنطقة الشــرقية‬\n\n\n‫‪225‬‬\n\f‫واملتعلقــة بدعــوى وبرفقهــا القــرار الصــادر مــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة رقــم ‪ 33428858‬وتاريــخ ‪1433/10/17‬ه ـ املتضمــن أنــه لوحــظ‬\n‫أن املدعــي اعتــرض علــى احلكــم ولــم ترفــق لــه الئحــة ولــم يذكــر شــيء‬\n‫بخصــوص االعتــراض والبــد مــن ذلــك وجوابـ ًا عــن ذلــك فــإن املذكــور‬\n‫املعتــرض علــى احلكــم قــد رفــض التوقيــع علــى الضبــط فتــم إفهامــه‬\n‫بأنــه ســوف يســقط حقــه يف تقــدمي الالئحــة االعتراضيــة وبالفعــل أعطــي‬\n‫مــدة شــهر ولــم يوقــع علــى الضبــط كمــا لــم يقــدم الئحــة اعتراضيــة‬\n‫عليــه وقــد أوضحنــا ذلــك عنــد تــاوة احلكــم عليــه لــذا فاإلجــراء مــا‬\n‫تقــدم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪1433/11/24‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":222,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a711beb4d294a179abb104543031f696d7cd0f8dc9ebd64bb6fbd57df8268e55","normalized_text_hash":"9806583629015ea4a761f5dd3ff3c1e402bca87852c13f3e1bd040097930249b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p222-33361564"},{"id":"00c70cd6-9381-57c8-b3cd-33bbc37ca079","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء غير -سب وتلفظ -طلب تعزير املدعى عليه لقاء تلفظه -إقرار املدعى عليه -املسلم من سلم املسلمون من لسانه ويده - تعذر الصلح بن الطرفن -تعزير املدعى عليه باجللد لقاء تلفظه","document_number":"34168835","case_number":"33131997","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"إيذاء غير -سب وتلفظ -طلب تعزير املدعى عليه لقاء تلفظه -إقرار املدعى عليه -املسلم من سلم املسلمون من لسانه ويده - تعذر الصلح بن الطرفن -تعزير املدعى عليه باجللد لقاء تلفظه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34168835 :‬‬\n                         ‫َر ْق ُم الدعوى‪33131997 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34246763‬تاريخه‪ 1434/06/20 :‬هـ‬\n\n\n      ‫إيــذاء غيــر ‪ -‬ســب وتلفــظ ‪ -‬طلــب تعزيــر املدعــى عليــه لقــاء تلفظــه‬\n      ‫‪ -‬إقــرار املدعــى عليــه ‪ -‬املســلم مــن ســلم املســلمون مــن لســانه ويــده ‪-‬‬\n      ‫تعــذر الصلــح بــن الطرفــن ‪ -‬تعزيــر املدعــى عليــه باجللــد لقــاء تلفظــه‬\n                                                                     ‫علــى املدعــي ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                                ‫ومالــه وعرضــه ) ‪.‬‬\n      ‫‪ .2‬قوله صلى اهلل عليه وســلم ‪ ( :‬املســلم من ســلم املســلمون من لســانه‬\n                                                                          ‫و يــده ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليــه بأنــه قــام بســبه والتلفــظ عليــه و يطلــب‬\n      ‫تعزيــره لذلــك ـ صــادق املدعــى عليــه علــى دعــوى املدعــي وذكــر أن‬\n      ‫املدعــي عليــه لــه قضايــا كثيــرة يف احملاكــم فقلــت لــه ‪( :‬خــاف اهلل)‬\n      ‫ثــم رد عليــه بألفــاظ بذيئــة ال يذكرهــا ثــم تلفــظ عليــه بألفــاظ بذيئــة‬\n      ‫ال يذكرهــا ثــم ذكــر أنــه ســريع الغضــب ويصــدر منــه مــا ال يرتضيــه‬\n      ‫ويراجــع يف العيــادات النفســية ولديــه تقاريــر طبيــة يف انفعاالتــه ـ أبــرز‬\n      ‫املدعــى عليــه تقريــر ًا طبي ـ ًا مــن مستشــفى الصحــة النفســية أشــير إلــى‬\n\n‫‪227‬‬\n\f‫رقمــه وتاريخــه يتضمــن أن املدعــى عليــه لديــه اضطــراب وجدانــي‬\n‫كمــا أبــرز تقريــر ًا صــادر ًا مــن مستشــفى آخــر بــدون رقــم وتاريــخ‬\n‫مكتوب ـ ًا باللغــة اإلجنليزيــة ـ قــرر املدعــى عليــه أنــه ال يطالــب املدعــي‬\n‫بخصــوص تلفظــه عليــه بشــيء ـ وبعــرض ذلــك علــى املدعــي أنكــر مــا‬\n‫ذكــره املدعــى عليــه مــن تلفظــه علــى املدعــى عليــه بــأي لفــظ مشــن ـ‬\n‫جــرى عــرض الطرفــن علــى جلنــة الصلــح وقــد تعــذر اإلصــاح بينهمــا ـ‬\n‫ونظــر ًا ألن تلفــظ املدعــى عليــه علــى املدعــي بألفــاظ بذيئــة فعــل محــرم‬\n‫شــرع ًا يســتحق العقــاب عليــه ـ ونظــر ًا لقولــه صلــى اهلل عليــه وســلم ‪:‬‬\n‫(كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه ) وإلقــرار املدعــى‬\n‫عليــه بتلفظــه علــى املدعــي ـ ونظــر ًا حلالــة املدعــى عليــه النفســية وحيــث‬\n‫تعــذر الصلــح بــن الطرفــن ـ صــدر احلكــم بتعزيــر املدعــى عليــه باجللــد‬\n‫عشــرين جلــدة دفعــة واحــدة وأخــذ التعهــد عليــه بلــزوم االســتقامة وعــدم‬\n‫العــودة ملــا بــدر منــه ـ قــرر املدعــي القناعــة وقــرر املدعــى عليــه اعتراضــه‬\n‫علــى احلكــم بالئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف ـ صــدق‬\n                                         ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪ 33131997‬وتاريــخ‬\n‫‪ 1433/02/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33344842‬وتاريــخ‬\n‫‪ 1433/02/21‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي‪ ....... /‬ســعودي اجلنســية‬\n\n                                                                                         ‫‪228‬‬\n\f      ‫حامــل الســجل املدنــي رقــم ( ‪ ) .......‬وحضــر حلضــوره املدعــى عليــه‪/‬‬\n      ‫‪ .......‬ســعودي اجلنســية حامــل الســجل املدنــي رقــم ( ‪ ) .......‬وقــرر املدعــي‬\n      ‫دعــواه قائــا أننــي كنــت متواجــدا يف أحــد محــات إصــاح اإلطــارات‬\n      ‫مبحافظــة ‪ ...‬وأثنــاء ذلــك حضــر املدعــى عليــه واســتقبلته للســام عليــه‬\n      ‫وال توجــد بينــي وبينــة معرفــة ملحــة وبادرنــي قائــا أنــت ‪ .......‬؟ فقلــت‬\n      ‫لــه نعــم فقــال (والتــراب وراك تشــكي ‪ .......‬فقلــت لــه صــل علــى النبــي‬\n      ‫فقــال اهلل يلعنــك ويلعــن أبــوك وجــدك وإذا لزمتــك انــي ال طــي يف‬\n      ‫بطنــك ) أطلــب تعزيــر املدعــى عليــه لقــاء تلفظــه بالســجن أو اجللــد هــذه‬\n      ‫ا لقــد حضــرت‬   ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫للمدعــي كمــا ذكــره بدعــواه وملــا علمــت أنــه هــو ‪ .......‬قلــت لــه خــاف‬\n      ‫اهلل وذكرتــه بــاهلل حيــث إن للمدعــي دعــاوي كثيــرة يف احملاكــم‬\n      ‫وخصوصــا يف محكمــة ‪ ...‬ثــم رد علــي بألفــاظ بذيئــة ال أذكرهــا ثــم‬\n      ‫تلفظــت عليــه أنــا أيضــا بألفــاظ بذيئــة ال أتذكرهــا وأنــا رجــل ســريع‬\n      ‫الغضــب ويصــدر منــي حــال الغضــب مــا ال أرتضيــه والقضيــة مضــى‬\n      ‫عليهــا مايزيــد علــى الســنة فــا أتذكــر ماقلتــه لــه مــن ألفــاظ علــى‬\n      ‫وجــه التحديــد وأنــا أراجــع العيــادات النفســية ولــدي تقاريــر طبيــة يف‬\n      ‫إنفعاالتــي هكــذا أجــاب ثــم أبــرز املدعــى عليــه أصــل التقريــر الطبــي‬\n      ‫رقــم ( ‪ ) .......‬وتاريــخ ‪1433/6/2‬ه ـ الصــادر مــن مستشــفى الصحــة‬\n      ‫النفســية بالطائــف املتضمــن أن لــدى املدعــى عليــه إضطــراب وجدانــي‬\n      ‫كمــا أبــرز أصــل تقريــر طبــي صــادر مــن مجموعــة مستشــفيات ‪...‬‬\n      ‫بــدون رقــم وبــدون تاريــخ وقــد كتــب باللغــة اإلجنليزيــة وأضــاف املدعــى‬\n      ‫عليــه قائــا أننــي ال أطالــب املدعــي بخصــوص تلفظــة علــي بشــئ البتــة‬\n      ‫هكــذا أجــاب وبعــرض ماقــرره املدعــى عليــه علــى املدعــي أجــاب قائــا‬\n\n\n‫‪229‬‬\n\f‫أننــي لــم أتلفــظ عليــه بــأي لفــظ مشــن البتــة هكــذا أجــاب فبنــاء‬\n‫علــى ماتقــدم مــن الدعــوى واألجابــة وإلقــرار املدعــى عليــه بتلفظــه‬\n‫علــى املدعــي بألفــاظ بذيئــة ولقــول النبــي صلــى اهلل عليــه وســلم (كل‬\n‫املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه ) ولقولــه عليــه الســام‬\n‫(املســلم مــن ســلم املســلمون مــن لســانه ويــده) ومبــا أن تلفــظ املدعــى‬\n‫عليــه علــى املدعــي بألفــاظ بذيئــة فعــل محــرم شــرعا يســتحق العقــاب‬\n‫عليــه ونظــرا حلــال املدعــى عليــه النفســية وحيــث جــرى عــرض الطرفــن‬\n‫علــى جلنــة اإلصــاح بهــذة احملكمــة بخطابنــا رقــم ‪ )33344872‬وتاريــخ‬\n‫‪1434/2/3‬ه ـ وقــد تعــذر اإلصــاح بينهمــا فلمــا ســبق فقــد ثبــت لــدي‬\n‫تلفــظ املدعــى عليــه علــى املدعــي بألفــاظ بذيئــة وحكمــت علــى املدعــى‬\n‫عليــه تعزيــرا مبــا يلــي أوال ‪ :‬يجلــد املدعــى عليــه ‪ ....... /‬عشــرين جلــدة‬\n‫دفعــة واحــدة ثانيــا ‪ :‬يؤخــذ التعهــد علــى املدعــى عليــه بلــزوم اإلســتقامة‬\n‫وعــدم العــودة ملابــدر منــه وبعــرض احلكــم علــى الطرفــن قــررا ملدعــي‬\n‫قناعتــة كمــا قــرر املدعــى عليــه عــدم قناعتــة طالبــا رفعــه حملكمــة‬\n‫اإلســتئناف مــع تقــدمي الئحــة إعتراضيــة عليــه فأفهمتــه بــأن لــه إســتالم‬\n‫نســخة مــن احلكــم يف هــذا اليــوم األحــد ‪1434/3/22‬ه ـ وأن مهلــة‬\n‫اإلعتــراض علــى احلكــم وقدرهــا ثالثــون يومــا ســوف حتســب إعتبــارا‬\n‫مــن تاريــخ هــذا اليــوم فــإن مضــت املــدة دون تقــدمي اعتراضــه فــإن حقــه‬\n‫يف تقــدمي االعتــراض عليــه يكــون ســاقطا وعلــى ذلــك جــرى التوقيــع‬\n‫وكان ختــام اجللســة الســاعة احلاديــة عشــرة صباحــا وبــاهلل التوفيــق‬\n                                         ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/04/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة صباحــا فبنــاء علــى انتهــاء مهلــة‬\n\n\n                                                                                     ‫‪230‬‬\n\f      ‫االعتــراض حيــث أفهــم املدعــى عليــه بــأن لــه مهلــة ثالثــن يومــا اعتبــارا‬\n      ‫مــن تاريــخ ‪1434/03/22‬ه ـ لتقــدمي اعتراضــه وعليــه فقــد ســقط حــق‬\n      ‫املدعــى عليــه يف تقــدمي الئحتــه اإلعتراضيــة وأمــرت برفــع احلكــم‬\n      ‫حملمــة اإلســتئناف مبكــة املكرمــة لتدقيقــة ولئــا يخفــى جــرى أثباتــه‬\n      ‫وكان ختــام اجللســة الســاعة الثامنــة والنصــف صباحــا وبــاهلل التوفيــق‬\n                   ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                 ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة رقــم(‪)33828246‬‬\n      ‫وتاريخ(‪1434/6/11‬هــ) املرفــق بهــا الصــك رقــم(‪)34168835‬‬\n      ‫وتاريخ(‪1434/3/22‬هـ)الصــادر مــن فضيلــة الشــيخ‪ ....... /‬القاضــي‬\n      ‫باحملكمــة اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى‪ ....... /‬ســعودي اجلنســية‬\n      ‫ضــد‪ ، ....... /‬املتهــم يف التلفــظ بألفــاظ بذيئــة احملكــوم فيــه مبــا‬\n      ‫دون باطنــه ‪ ، ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                        ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪231‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":227,"source_page_end":231,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38caf7d3ef19de8e425160ec1c2386badbaf6715957b9116512a2336c9fce0ee","normalized_text_hash":"3c7321e35f9751a9941238b541853c746dac343ac51b9a6fe10931946b85e228","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p227-34168835"},{"id":"aab98a11-8bd0-55b6-8aab-d59a7721fc96","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة - حق املدعي يف قبول أو عدم قبول مين املدعى عليه بنفي الدعوى","document_number":"33470723","case_number":"33207246","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/30","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة - حق املدعي يف قبول أو عدم قبول مين املدعى عليه بنفي الدعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/30 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33470723 :‬‬\n                    ‫َر ْق ُم الدعوى‪33207246 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34227585‬تاريخه‪1434/5/29 :‬هـ‬\n\n\n ‫إيــذاء الغيــر (حــق خــاص) ‪ -‬اعتــداء بالضــرب ‪ -‬مطالبــة املدعــي‬\n ‫باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــي غيــر موصلــة ‪-‬‬\n ‫حــق املدعــي يف قبــول أو عــدم قبــول ميــن املدعــى عليــه بنفــي الدعــوى‬\n                                                              ‫‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                           ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بضربــه علــى وجهــه بيــده‪ ،‬وطلــب‬\n ‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء‬\n ‫يف الدعــوى‪ -‬أحضــر املدعــي شــاهد ًا فلــم تقبــل احملكمــة شــهادته‬\n ‫ألنهــا تضمنــت مــا يفيــد كونــه طرفــا يف اخلصومــة‪ -‬املدعــي لــم يقــم‬\n ‫بينــة موصلــة إلثبــات دعــواه ولــم يقبــل ميــن خصمــه علــى نفيهــا‪ -‬قضــت‬\n ‫احملكمــة بعــدم ثبــوت دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه منها‪-‬‬\n ‫قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                        ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n                                                                                     ‫‪232‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                                 ‫ّ‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 33207246‬وتاريــخ‬\n      ‫‪1433/03/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33550726‬وتاريــخ‬\n      ‫‪1433/03/22‬ه ـ ففــي يــوم األحــد املوافــق ‪1433/05/23‬ه ـ افتتحــت‬\n      ‫اجللســة االولــى الســاعة الثانيــة عشــر والنصــف وفيهــا حضــر (‪).....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).....‬وقــد جــرى طلــب‬\n      ‫املدعــى عليــه باخلطــاب رقــم ‪ 33/550726‬وتاريــخ ‪1433/3/30‬ه ـ‬\n      ‫فوردنــي إفــادة مديــر وحــدة اإلحضــار بهــذه احملكمــة برقــم ‪682‬‬\n      ‫وتاريــخ ‪1433/5/4‬ه ـ املتضمــن مــا نصــه ( نفيــد فضيلتكــم بأنــه مت‬\n      ‫طلــب املذكوريــن هاتفيــا واســتعد باحلضــور علــى حســب احملضــر‬\n      ‫املرفــق واملتضمــن مراجعــة فضيلــة القاضــي الشــيخ ‪ ).....(/‬باملوعــد‬\n      ‫احملــدد مــن فضيلتــه ) أ ‪.‬ه ـ وقــد وردنــي خطــاب املدعــى عليــه (‪).....‬‬\n      ‫املقيــد بهــذه احملكمــة برقــم ‪ 926434‬وتاريــخ ‪1433/5/17‬ه ـ‬\n      ‫املتضمــن مــا نصــه ( أقــدم لفضيلتكــم بخطابــي هــذا راجيــا مــن اهلل‬\n      ‫ثــم منكــم قبــول اعتــذاري مــن احلضــور للجلســة املقــررة لــدى فضيلــة‬\n      ‫الشــيخ بخصــوص دعــوى ضــدي يــوم األحــد املوافــق ‪1433/5/23‬ه ـ‬\n      ‫الســاعة العاشــرة والنصــف صباحــا حيــث أننــي خــارج البــاد بدولــة‬\n      ‫األردن ملناقشــة رســالة املاجســتير يف إحــدى اجلامعــات بــاألردن ) أ ‪ .‬ه ـ‬\n      ‫وبســؤال املدعــي عــن دعــواه قــرر قائــا بتاريــخ ‪1433/3/4‬ه ـ راجعــت‬\n      ‫مكتــب عمــدة قريــة ‪ ....‬وكان أخــوه يف مكتبــه فحصلــت بينــي وبــن‬\n\n‫‪233‬‬\n\f‫أخيــه مشــادة كالميــة فخــرج أخــاه وضربنــي كفــا علــى وجهــي لــذا‬\n‫اطلــب احلكــم علــى بحقــي الشــرعي هــذه دعــواي ولــدي أنــا ‪ ....‬القاضــي‬\n‫باحملكمــة اجلزائيــة باألحســاء القائــم بعمــل املكتــب القضائــي الثامــن‬\n‫املكلــف برقــم ‪ 33393416‬وتاريــخ ‪1433/06/10‬ه ـ ويف يــوم األحــد‬\n‫املوافــق ‪1433/7/20‬ه ـ افتتحــت اجللســة الثانيــة يف متــام الســاعة‬\n‫التاســعة اخلاصــة بدعــوى ضــد وفيهــا حضــر ‪ ...‬املدعــي وحضــر ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم بصفتــه وكيــا عــن املدعــى‬\n‫عليــه مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باإلحســاء‬\n‫برقــم ‪ 33172820‬وتاريــخ ‪1433/7/14‬ه ـ املخــول لــه يف املطالبــة‬\n‫وإقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى والــرد عليهــا‬\n‫واإلقــرار والصلــح والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع عنــه‬\n‫وإحضــار الشــهود والبينــات والطعــن فيهــا و اإلجابــة واجلــرح والتعديــل أ‪.‬‬\n‫ه ـ وبعــرض الدعــوى علــى املدعــى عليــه وكالــه أجــاب قائــا أن هــذه‬\n‫الدعــوى باطلــه وكيديــه واطلــب تعزيــر املدعــي لقــاء ذلــك هكــذا‬\n‫أجــاب وبســؤال املدعــي هــل لديــه بينــه علــى دعــواه أجــاب قائــا لــدي‬\n‫شــاهدين وهمــا و هكــذا أجــاب لــذا أجبتــه لطلبــه ورفعــت اجللســة‬\n‫ويف جلســة أخــرى وفيهــا حضــر املدعــي كمــا حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم وبعــرض الدعــوى علــى املدعــى عليــه أجــاب‬\n‫قائــا مــا ذكــره املدعــي غيــر صحيــح فلــم أضربــه كــف علــى وجــه‬\n‫وإمنــا تخاصــم املدعــي مــع أخــي وفرقــت بينهمــا هكــذا أجــاب وبعرضــه‬\n‫علــى املدعــي قــرر قائــا الصحيــح مــا ذكرتــه وبينتــي علــى ذلــك قــد‬\n‫أحضرتهــا وأطلــب ســماعها واطلــب ســماع مــا لــدي مــن شــهادة هكــذا‬\n‫قــرر ثــم احضــر الشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n                                                                                  ‫‪234‬‬\n\f      ‫املدنــي رقــم ‪ ...‬وقــرر قائــا اشــهد أن هــذا احلاضــر اتصــل علــى والــدي‬\n      ‫كــي نســتلم أوراق جمعيــة البــر اخليريــة يف قريــة ‪ ...‬ثــم حضــرت أنــا و‬\n      ‫إلــى مكتــب العمــدة هــذا احلاضــر فســألنا مــن طــرق البــاب فقلــت انــا‬\n      ‫الــذي طرقتــه فقــال إن مديــر شــرطة يســتدعيك ثــم دخــل اخــو العمــدة ثــم‬\n      ‫ســأل مــن طــرق البــاب فأجبتــه أنــا ثــم رفــع صوتــه وقــال إنكــم تكلمتــم‬\n      ‫علــى أهلــي وقــال نحــن نتكلــم مــع العمــدة ثــم رفــع صوتــه علــى وكان‬\n      ‫العمــدة يتحــدث مــع وأثنــاء ذلــك حصــل مشــادة بــن و ثــم قــام العمــدة‬\n      ‫بكــزه واخــرج أخــوه ورجــع إلــى ثــم ضربــه كــف بيــده اليمــن علــى‬\n      ‫خــده األيســر هــذا مــا لــدي وبــه اشــهد وبعــرض الشــاهد وشــهادته علــى‬\n      ‫املدعــى عليــه قــرر قائــا ال اعــرف عــن الشــاهد شــيء وشــهادته بعضهــا‬\n      ‫صحيــح وبعضهــا غيــر صحيــح والصحيــح انــي اتصلــت علــى والــده وقلــت‬\n      ‫لــه احضــر أنــت بنفســك لتســتلم املعاملــة التــي تخصــك فأتــوا ابنــاه‬\n      ‫وجلســوا عنــدي يف املكتــب ثــم ســألتهم عــن أســمائهم وعرفــت والدهــم‬\n      ‫وقلــت والدكــم صاحــب قــدمي وأنــا ســامحتكم وكنــت قبــل ذلــك أنــي‬\n      ‫اتصــل علــى شــرطة املبــرز وأخبرتهــم بــان فيــه أشــخاص تلفظــوا علــى‬\n      ‫أهلــي ونصحتهــم وكان حاضــرا شــاهدا وهــذا فقــط هــو الصحيــح أمــا‬\n      ‫بقيــة مــا ذكــره فغيــر صحيــح هكــذا قــرر وبســؤال املدعــي هــل لديــه‬\n      ‫زيــادة بينــه قــرر قائــا إن الشــاهد لــن يحضــر إلــى احملكمــة محتجــا‬\n      ‫بنســيان الشــهادة وال ســلطة لــي علــى إحضــاره هكــذا قــرر كمــا قــرر‬\n      ‫املدعــى عليــه قائــا إن الشــاهد أدلــى بشــهادته لــدى شــرطة ‪ ...‬واطلــب‬\n      ‫الرجــوع إليهــا هكــذا قــرر وبالرجــوع إليهــا اطلعــت علــى الصفحتــن‬\n      ‫‪ 14.15‬مــن اللفــة الثانيــة فوجدتهــا تتضمــن أقــوال الشــاهد املتضمنــة مــا‬\n      ‫نصــه (أفيدكــم انــه يف حوالــي الســاعة الثامنــة مســاء مــن يــوم اجلمعــة‬\n\n\n‫‪235‬‬\n\f‫املوافــق ‪1433/3/4‬ه ـ أثنــاء زيارتــي ملكتــب العمــدة بقصــد املراجعــة‬\n‫ويف أثنــاء جلوســي باملكتــب والعمــدة حضــر أبنــاء املدعــو وال اعلــم عــن‬\n‫ســبب مراجعتهــم وقــام العمــدة بــاألذن لهــم باجللــوس واحلديــث معهم حول‬\n‫معرفتــه لوالدهــم وانــا مســامحكم بالــذي حــدث منكــم وحدث كالم‬\n‫بينهــم حــول أنهــم كانــا يدرســان يف حلقة املســجد وبعدها حضر املدعو‬\n‫شــقيق العمــدة وقــام بالتحــدث مــع وحدثــت بينهــم مشــادة كالميــة فقــام‬\n‫العمــدة بالتدخــل بينهــم وفــك النــزاع حيــث قــام بدفــع أخيــه إلــى خــارج‬\n‫املكتــب وقــام بدفــع املدعــو بيــده اليمــن مــن قــوة التشــابك ممــا أدى‬\n‫ارتطــام يــده اليمنــى علــى وجهــه مــن اجلهــة اليمنــى وحســب مــا أراه انــه‬\n‫كان بقصــد فــك النــزاع ولــم يكــن القصــد االعتــداء) أ ‪ .‬ه ـ ويف جلســة‬\n‫أخــرى وفيهــا حضــر املدعــي واملدعــى عليــه وبعــرض مــا ورد يف أقــوال‬\n‫الشــاهد علــى املدعــي قــرر قائــا إن أقــوال الشــاهد متناقضــة وســمعته‬\n‫يقــول حصــل مشــادة كالميــة وضربنــي املدعــى عليــه ومــا هــو مــدون‬\n‫يقــول أن الضربــة حصلــت مــن غيــر قصــد لهــا واننــي قــد وكلــت أخــي‬\n‫هــذا احلاضــر يف املطالبــة واملدافعــة واملرافعــة واإلقــرار واإلنكار وإقامة‬\n‫الدعــوى والــرد عليهــا والصلــح والتنــازل وقبــول احلكــم واالعتــراض‬\n‫عليــه هكــذا قــرر كمــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ...‬وقــرر كل مــن املدعــي اصالــه ووكالــة قائــا أننــي ال‬\n‫أطالــب ميــن املدعــى عليــه علــى نفــي هــذه الدعــوى هكــذا قــرر وقــد‬\n‫قــرر املدعــى عليــه قائــا ان يــدي اليســرى أثنــاء تفريقــي بــن ضربــت‬\n‫رقبتــه هــذا كل مــا حصــل وبينــي وبــن الشــاهد خصومــه وهــو ســبب‬\n‫هــذه املشــكلة هكــذا قــرر فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة‬\n‫وإنــكار املدعــى عليــه للدعــوى نظــرا لكــون الشــاهد قــد ضمــن‬\n\n\n                                                                                    ‫‪236‬‬\n\f      ‫شــهادته مــا يفيــد بوجــود طــرف لــه يف هــذه اخلصومــة وبنــاء علــى مــا‬\n      ‫قــرره املدعــي مــن كونــه ليــس لــه اال هــذا الشــاهد وان الشــاهد اآلخــر‬\n      ‫احتــج بنســيان موضــوع الدعــوى ومــا قــرره املدعيــان أصالــة ووكالــة مــن‬\n      ‫عــدم طلــب اليمــن علــى نفــي الدعــوى وبنــاء علــى ذلــك كلــه فلــم تثبــت‬\n      ‫لــدي هــذه الدعــوى وأخليــت ســبيل املدعــى عليــه منهــا وبــه حكمــت‬\n      ‫وبعرضــه علــى الطرفــن قــرر املدعــي أصالــة ووكالــة عــدم قناعتهمــا بــه‬\n      ‫واســتعدا بتقــدمي الئحــة اعتراضيــه فأفهمتهمــا باملراجعــة يــوم األربعــاء‬\n      ‫املوافــق ‪1433/12/1‬ه ـ الســتالم نســخه مــن احلكــم لتقــدمي اعتراضــه‬\n      ‫عليــه يف مــده أقصاهــا شــهر مــن تاريخــه ففهمــا ذلــك وقــرر املدعــى عليــه‬\n      ‫قناعتــه بــه وأقفلــت اجللســة الســاعة الثانيــة عشــرة وخمســة وأربعــون‬\n      ‫دقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                     ‫وســلم حــرر يف ‪1433/11/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة االحســاء املكلف برقم‬\n      ‫‪ 33/2040703‬وتاريــخ ‪1434/4/28‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 341071814‬وتاريــخ ‪1434/5/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪33470723‬‬\n      ‫وتاريــخ ‪1433/11/30‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‪ ).....(/‬يف قضيــة‬\n      ‫اعتــداء علــى اخــر وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم حــرر يف ‪1434/5/29‬هــ‪.‬‬\n\n\n‫‪237‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":232,"source_page_end":237,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"556f4161c93d9707b377e4dc86f1827ab74680311fa739855410b76de9e73308","normalized_text_hash":"86deb04549e19d96bcfbc0f90b102a4626591ef75308b2f2d9b4acaa615055c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p232-33470723"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7ffe0ca6-6a9e-5f26-b9ac-d4026ba227d7","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالتلفظ يف صحيفة دعوى - مطالبة املدعي باملجازاة -انكار وكيل املدعى عليه الدعوى عنه -عدم مسؤولية الوكيل عن عبارات السب التي أوردها موكله يف صحيفة الدعوى -رد الدعوى.","document_number":"34329653","case_number":"3497172","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/13","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالتلفظ يف صحيفة دعوى - مطالبة املدعي باملجازاة -انكار وكيل املدعى عليه الدعوى عنه -عدم مسؤولية الوكيل عن عبارات السب التي أوردها موكله يف صحيفة الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/13 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34329653 :‬‬\n                           ‫َر ْق ُم الدعوى‪3497172 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34383132‬تاريخه‪1434/2/22 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالتلفــظ يف صحيفــة دعــوى ‪-‬‬\n       ‫مطالبــة املدعــي باملجــازاة ‪ -‬انــكار وكيــل املدعــى عليــه الدعــوى عنــه‬\n       ‫‪ -‬عــدم مســؤولية الوكيــل عــن عبــارات الســب التــي أوردهــا موكلــه يف‬\n                                                ‫صحيفــة الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n                                        ‫قول اهلل تعالى‪ (( :‬وال تزر وازرة وزر أخرى ))‪.‬‬\n\n\n\n\n       ‫ادعــى وكيــل املدعــي علــى املدعــى عليــه بأنــه قــد تلفــظ علــى موكلــه‬\n       ‫مبــا جــاء يف دعــواه وذلــك يف صحيفــة دعــوى قدمهــا إلــى احملكمــة‬\n       ‫تتعلــق بقضيــة حضانــة بــن موكلــه وزوجتــه‪ ،‬وطلــب احلكــم عليــه‬\n       ‫بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر وكيــل املدعــى عليــه مــا جــاء يف‬\n       ‫دعــوى املدعــي ودفــع بــأن موكلــه ناقــل لوجهــة نظــر موكلتــه (يف قضية‬\n       ‫احلضانــة) ودوره هــو متثيلهــا يف الدعــوى‪ ،‬كمــا أن الصحيفــة املذكــورة‬\n       ‫ليســت مــن إعــداده بــل مــن إعــداد موكلتــه وبالتالــي فــا يوجــد ســبب‬\n       ‫الختصــام املدعــي مــع موكلــه‪ -‬املدعــى عليــه ال يتكلــم عــن نفســه‬\n       ‫وإمنــا ناقــل لوجهــة نظــر موكلتــه‪ -‬قضــت احملكمــة بصــرف النظــر عــن‬\n       ‫دعــوى املدعــي‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي ‪ -‬قــررت‬\n\n‫‪201‬‬\n\f             ‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 3497172‬وتاريــخ ‪1434/02/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34503559‬وتاريــخ ‪1434/2/27‬ه ـ ففــي يوم اخلميس‬\n‫املوافــق ‪1434/08/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 :15‬وفيهــا حضــر‬\n‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).....‬وكيــا عــن‬\n‫مبوجــب الوكالــة رقــم (‪ )34130943‬وتاريــخ ‪1434/02/04‬ه ـ والتــي‬\n‫تخــول لــه املرافعــة واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار‬\n‫والصلــح والتنــازل وطلــب اليمــن ورده واالمتنــاع عنــه واملطالبــة بتنفيــذ‬\n‫األحــكام وقبولهــا والــرد عليهــا واالعتــراض عليهــا وطلــب االســتئناف‬\n‫وادعــى علــى احلاضــر معــه‪ ).....( /‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).....‬مبوجــب الوكالــة رقــم (‪ )34345133‬وتاريــخ‬\n‫‪1434/3/21‬ه والتــي تخــول لــه املرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل واإلبــراء وطلــب‬\n‫اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا‬\n‫والتنفيــذ وطلــب التحكيــم واملطالبــة بتنفيــذ األحــكام وقبــول احلكــم‬\n‫ونفيهــا واالعتــراض علــى األحــكام وطلــب االســتئناف قائــا يف دعــواه‬\n‫إن مــوكل هــذا احلاضــر قــد تلفــظ علــى موكلــي يف صحيفــة الدعــوى‬\n‫املقدمــة يف احملكمــة العامــة يف الريــاض لــدى فضيلة القاضي يف دعوى‬\n‫حضانــة وأتهمــه بالتواطــؤ مــع الشــيطان يف حتقيــق مــراده وانشــغاله‬\n\n                                                                                   ‫‪202‬‬\n\f      ‫يف شــهوات ملــذات الدنيــا حتــى أصبــح عــدمي االحســاس باألبــوة وأنــه‬\n      ‫متجــرد مــن الشــفقة واالنســانية وإنــي تعهــدت بإصــاح نفســي ونكثــت‬\n      ‫عــن الشــرط أطلــب مجازاتــه علــى هــذا االتهــام وبســؤال املدعــى عليــه‬\n      ‫أجــاب مــا ذكــره املدعــي كلــه غيــر صحيــح و يدفــع موكلــي بدفعــه‬\n      ‫الشــكلي ألن الدعــوى أقيمــت علــى مــن ال يصــح اختصامــه حيــث أن‬\n      ‫ـام وقــد تــوكل عــن الســيدة‪ ).....(/‬مبوجــب الوكالــة‬   ‫موكلــي يعمــل محـ ٍ‬\n      ‫رقــم ‪ 3470551‬وتاريــخ ‪1434/1/19‬ه ـ ومثلهــا يف قضيتــن األولــى‬\n      ‫حضانــة والثانيــة نفقــة واملنظــورة لــدى فضيلــة الشــيخ‪ ).....(/‬القاضــي‬\n      ‫باحملكمــة العامــة بالريــاض وبالتالــي فــإن موكلــي هــو ناقــل لوجهــة‬\n      ‫نظــر موكلتــه وكمــا يعلــم فضيلتكــم أن الوكيــل ال يكلــف وال‬\n      ‫يحلــف إذ أن دوره هــو متثيــل ملوكلــه وناقــل ألقوالــه‪ ،‬والدليــل علــى ذلــك‬\n      ‫مــا ورد صريح ـ ًا يف نــص املــادة (‪ )13‬مــن نظــام احملامــاة والتــي تنــص‬\n      ‫علــى « للمحامــي أن يســلك الطريقــة التــي يراهــا ناجحــة يف الدفــاع عــن‬\n      ‫موكلــه‪ ،‬وال جتــوز مســاءلته عمــا يــورده يف مرافعته كتابي ًا أو مشــافهة‬\n      ‫ممــا يســتلزمه حــق الدفــاع « ولــم يحيــد موكلــي عمــا نــص عليــه نظــام‬\n      ‫احملامــاة وموكلــي ملتــزم متامـ ًا مبــا مت ضبطــه يف صــك احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ ).....( /‬قضيــة احلضانــة وهــو مســئول عمــا يــرد يف‬\n      ‫ضبــط اجللســة دون ســواه‪ ،‬لــذا فــإن موكلــي يتمســك بالدفــع الشــكلي‪.‬‬\n      ‫ثانيـاً‪ :‬مــن حيــث املوضــوع‪ :‬يف البدايــة يتمســك موكلــي بإقــرار املدعــي‬\n      ‫يف مجلــس القضــاء علــى صحــة دعــوى موكلتــه يف احلضانــة والتــي صدر‬\n      ‫بهــا الصــك رقــم (‪ )3432451‬وتاريــخ ‪1434/2/9‬ه ـ حيــث أنــه أقــر‬\n      ‫وأكــد صحــة دعــوى موكلــة موكلــي فيمــا ذكرتــه‪ .1.‬مــن الواضــح‬\n      ‫أن املدعــي أقــام هــذه الدعــوى بعــد صــدور حكــم احلضانــة لصالــح‬\n\n\n‫‪203‬‬\n\f‫موكلــة موكلــي رغبــة مــن املدعــي لثنــي موكلــي عــن مواصلــة القضيــة‬\n‫الثانيــة (النفقــة) والتــي ال تــزال منظــورة يف احملكمــة العامــة لــدى‬\n‫فضيلــة القاضــي ‪ .2‬مــا ارتكــن عليــه املدعــي يف مذكرتــه مــن صــدور‬\n‫مذكــرة قدمــت يف قضيــة احلضانــة فاملذكــرة ال حتمــل أي توقيــع عليها‬\n‫مــن موكلــي والواضــح أن موكلــة موكلــي قامــت بإعــداد املذكــرة‬\n‫ـاء علــى رغبتهــا بدليــل أنهــا علــى‬\n                                    ‫والتوقيــع عليهــا وأحضرهــا ملوكلــي بنـ ً‬\n‫أوراق بيضــاء وليســت علــى مطبوعــات احملامــي الرســمية باإلضافــة‬\n‫إلــى ذلــك درجــت العــادة أن قضايــا األحــوال الشــخصية تتــم مرافعتهــا‬\n‫شــفوي ًا أمــام ناظــر القضيــة حيــث أنهــا مــن القضايــا البســيطة كمــا‬\n‫هــو موضــح يف الصــك مــن القاضــي‪ .3 .‬بالرجــوع إلــى الئحــة الدعــوى‬\n‫محــل الــرد لــم جنــد حتديــد ًا للعبــارات بنــص صريــح وإمنــا ذكــر بعــض‬\n‫العبــارات وأورد معهــا تفســير ًا خاص ـ ًا باملدعــي وموكلــي ال يتحمــل أي‬\n‫تفســير إال مــا يصــدر منــه ال ســيما وأن تلــك العبــارات لــم متــس ذات‬\n‫املدعــي وســوف نــرد علــى مــا أورده مــن عبــارات وفــق تفســير موكلــة‬\n‫موكلــي باعتبــار أنهــا مــن كتبــت املذكــرة وهــي علــى النحــو اآلتــي‪ :‬أ‪.‬‬\n‫العبــارة اخلاصــة مــا أورده مــن تفســير أن موكلــي ذكــر أنــه متواطــئ مــع‬\n‫الشــيطان فهــذا قــول ال وجــود لــه إال لــدى املدعــي وحــده فقــط فاجلملــة‬\n‫املوجــودة يف املذكــرة هــي (حقــق مــراد الشــيطان بفعلــه) فنجــد أن‬\n‫املدعــي عمــد إلــى اقتضــاب اجلملــة وحتويرهــا بغيــر شــكلها األصلــي إذ‬\n‫أن املذكــرة التــي أخــذ منهــا نصــت مــا يلــي‪( :‬واســتجاب للشــيطان الــذي‬\n‫يريــد أن يــزرع الفتنــة والفــراق بــن األســر واملجتمعــات) فالــكالم هنــا‬\n‫ليــس لشــخص املدعــي وإمنــا قصــد بــه الشــيطان وذكــرت صفاتــه وأنــه‬\n‫بوجــود املشــاكل بــن املدعــي وموكلــة موكلــي هــو حتقيق ـ ًا لرغبــة‬\n\n\n                                                                                  ‫‪204‬‬\n\f      ‫الشــيطان لتفريــق األســرة واملجتمعــات‪ ،‬ومــن الواضــح مــن العبــارة التــي‬\n      ‫يف املذكــرة جــاءت للعــوام وليســت للتخصيــص لــذا فــإن هــذه العبــارة‬\n      ‫لــم تقصــد املدعــي بذاتــه‪ .‬ب‪ .‬أمــا مــا يخــص عبــارة (الشــهوات وامللــذات)‬\n      ‫فــإن هــذه عبــارة عائمــة فضفاضــة لــم يعنــي بهــا األمــور الســيئة فــكل مــا‬\n      ‫مييــل إليــه قلــب البشــر يعتبــر ملــذة وشــهوة‪ ،‬شــرب املــاء ملــذة‪ ،‬واالهتمــام‬\n      ‫بالدراســة ملــذة وشــهوة‪ ،‬وحــب املــال أيض ـ ًا وقــدوم اإلنســان علــى أمــر‬\n      ‫معــن يعتبــر ملهــي لــه ويعتبــر مــن ملــذات وشــهوات الدنيــا ومــا قصــد يف‬\n      ‫تلــك املذكــرة انكبــاب املدعــي يف عملــه ودراســته يف بريطانيــا وبعــده‬\n      ‫عــن أبنائــه وعــن أســرته وهــذا أمــر طبيعــي قــد يحصــل ألي شــخص‬\n      ‫متــزوج ولديــه أبنــاء فهــو مــن قبيــل االنشــغال بالشــهوات وملــذات النفــس‬\n      ‫املباحــة‪ ،‬لــذا فــان العبــارة ال تأخــذ باملعنــي الســيئ إذ أن ســياق القــول‬\n      ‫يفيــد انشــغال املدعــى بأحوالــه الشــخصية مــن دراســة وعمــل وليــس‬\n      ‫فيهــا أي تطــاول وكانــت مذكــورة مــن بــاب توضيــح الدفــوع لفضيلــة‬\n      ‫ناظــر القضيــة‪ .‬ج‪ .‬مســألة الوعــد والعهــد ونكثــه فــأي زوجــن قــد يقطــع‬\n      ‫لألخــر وعــد علــى نفســه بــأن ال يحــدث أي مشــاكل وحــال حصــول تلــك‬\n      ‫املشــاكل يعتبــر نكــث للوعــد‪ ،‬وموكلــة موكلــي رأت أن املدعــي قــد‬\n      ‫وعدهــا بعــدم حــدوث مشــاكل بينهمــا بــأن ال يعــود إلــى نفــس األســباب‬\n      ‫التــي تبعــث املشــاكل بينهمــا ولكــن ذلــك لــم يحصــل منــه وترتــب عليــه‬\n      ‫الطــاق واالنفصــال بينهمــا وقــد يكــون املدعــي فيــه نــوع مــن الغضــب‬\n      ‫أو التقصيــر وقــد وعــد موكلــة موكلــي بعــدم الغضــب أو التقصيــر إال‬\n      ‫انــه عــاد وحصــل اخلــاف فجعلــت ذلــك نكث ـ ًا للوعــود وللعهــود وليــس‬\n      ‫يف ذلــك أي تطــاول أو ســب‪ .‬د‪ .‬مــا يخــص مــا ذكــره املدعــي يف الئحتــه‬\n      ‫محــل الــرد وحتــت البنــد رقــم (‪ )5‬فــإن كل ذلــك جــاء بوصــف موكلــة‬\n\n\n‫‪205‬‬\n\f‫موكلــي ملــا حــدث لهــا مــن حرمــان مــن أبنائهــا أكثــر مــن ثمانيــة أشــهر‬\n‫دون أن تراهــم وكذلــك ســحبه مللفــات دراســتهم مــن املــدارس وتعطيلهم‬\n‫ا فــكان أقــرب وصــف لذلــك التصــرف مــا‬         ‫عــن الدراســة عام ـ ًا كام ـ ً‬\n‫ذكرتــه يف تلــك املذكــرة إن صحــة ذلــك‪ ،‬باإلضافــة إلــى غيــاب األب‬\n‫بالســفر للدراســة وتــرك األبنــاء لــدى اجلــد اعتبرتــه موكلــة موكلــي‬\n‫إهمــا ًال منــه وتقصيــر ًا بواجبــات األب مــا يخــص عبــارة « نســأل اهلل‬\n‫الســامة والعافيــة « فقــد ذكــرت كجملــة ختاميــة يف معــرض حديــث‬\n‫موكلــة موكلــي عــن حالهــا مــن امتنــاع املدعــي عــن النفقــة وحرمانهــا‬\n‫مــن أبنائهــا ونفقــات الــوالدة التــي لــم ينكرهــا املدعــي بــل أكدهــا‬\n‫بقولــه‪« :‬مــا ذكــره املدعــي وكالــة كلــه صحيــح جملــة وتفصيــا»‬\n‫وهــذه العبــارة يف حقيقتهــا دعــاء وتــودد ورجــاء مــن املولــى عــز وجــل‬\n‫تقــال يف الســراء والضــراء‪ .‬و‪ .‬يتضــح ملقــام فضيلتكــم أن موكلــي لــم‬\n‫يقــوم بالتطــاول علــى املدعــي أو ســبه أو حتــى املســاس بشــخصه وإمنــا‬\n‫هــو ناقــل عــن موكلتــه وكذلــك لــم يوجــد أي عبــارة مــن العبــارات التــي‬\n‫ذكرهــا فيهــا ســب لشــخص املدعــي وإمنــا عبــارات عاديــة ذكرتهــا‬\n‫موكلــة موكلــي لنقــل الصــورة التــي عانــت منهــا وكذلــك العبــارات‬\n‫ال حتمــل طابــع الســب أو التطــاول بــل طابــع الدفــاع عــن حقــوق موكلــة‬\n‫موكلــي ناهيــك انــه ال توجــد أي عالقــة أو ارتبــاط بــن املدعــى أصالــة‬\n‫وبــن موكلــي إال يف تلــك اجللســة التــي تقابــل فيهــا أول مــره وبالتالــي‬\n‫ال يوجــد أي ســبب شــرعي أو منطقــي يقبــل بــه خصومــة املدعــى مــع‬\n‫موكلــي‪ .‬ونؤكــد أن مــا ذكــر يف قضيــة احلضانــة والتــي كان يترافــع‬\n‫بهــا موكلــي قــد أقــر املدعــي يف تلــك اجللســة بــأن مــا ذكــر يف الدعــوى‬\n‫كلــه صحيــح جمل ـ ًة وتفصيــا‪ ،‬وهــذا إقــرار منــه بذلــك والقاعــدة‬\n\n\n                                                                                     ‫‪206‬‬\n\f      ‫الشــرعية تنــص (ال يجــوز اإلنــكار بعــد اإلقــرار إذ ال عــذر ملــن أقــر)‬\n      ‫وبإقــراره يف مجلــس القضــاء يثبــت مبــا ال يــدع مجــا ًال للشــك أن مــا نقلــه‬\n      ‫موكلــي صحيــح جمل ـ ًة وتفصي ـاً‪ .‬عليــه ولــكل مــا تقــدم التمــس مــن‬\n      ‫ال لعــدم وجــود الصفــة وموضوع ـ ًا لعــدم‬     ‫فضيلتكــم رد الدعــوى شــك ً‬\n      ‫وجــود أي ســب أو تطــاول والن دعــوى املدعــى ال وجاهــة لهــا شــرعا‬\n      ‫وبطلــب البينــة مــن املدعــي أجــاب لــدي صحيفة الدعــوى املقدمة لفضيلة‬\n      ‫ناظــر القضيــة واملرفقــة باملعاملــة باســم مطلقــة موكلــي ورفعــت اجللســة‬\n      ‫لالطــاع عليهــا ويف يــوم الثالثــاء املوافــق‪ 1434/10/13‬ه ـ وفيهــا حضــر‬\n      ‫الطرفــان فجــرى االطــاع علــى خطــاب مــن اربــع صفحــات وقــد ذكــرت‬\n      ‫هــذه االلفــاظ املذكــورة يف دعــوى املدعــي يف الصفحــة الثالثــة وبــدون‬\n      ‫توقيــع مــن املدعيــة او مــن احملامــي وبطلــب زيــادة بينــة أجــاب ليــس لــدي‬\n      ‫بينــة ســوى هــذا اخلطــاب وبعــرض ذلــك علــى املدعــى عليــه أجــاب ســبق‬\n      ‫ان اجبنــا عليــه يف اجللســة املاضيــة وان هــذا اخلطــاب قامــت بتوقيعــه‬\n      ‫موكلــة موكلــي وأن موكلــي مجــرد ناقــل وجهــة نظــر موكلتــه وبنــاء‬\n      ‫علــى مــا تقــدم ومــا جــاء يف دعــوى املدعــي وكالــة ومطالبتــه بتأديــب‬\n      ‫مــوكل املدعــى عليــه وحيــث ان املدعــى عليــه ال يتكلــم عــن نفســه وامنــا‬\n      ‫ناقــل وجهــة نظــر موكلتــه ولــو فتــح البــاب بتأديــب كل مــن تكلــم يف‬\n      ‫مجالــس القضــاة ومــا يصــدر مــن الفــاظ ألدى ذلــك إلى اشــغال احملاكم‬\n      ‫اجلزائيــة ومــا جــاء يف قصــة احلضرمــي والكنــدي ولقولــه تعالــى‪( :‬وال‬\n      ‫تــزر وازرة وزر أخــرى ) لــذا صرفــت النظــر عــن دعــوى املدعــي لعــدم‬\n      ‫ثبوتهــا وبعــرض احلكــم علــى املدعــي قــرر عــدم قناعتــه باحلكــم وطلــب‬\n      ‫االســتئناف وجــرى افهامــه بــأن مــده االعتــراض ثالثــن يومــا ابتــداء‬\n      ‫مــن اســتالم نســخة احلكــم وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪207‬‬\n\f‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/13‬ه ـ ويف يــوم‬\n‫الثالثــاء املوافــق‪ 1434/10/13‬ه ـ حضــر املدعــي وقــرر اســتالم نســخة‬\n‫مــن احلكــم‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34/503559‬‬\n‫وتاريــخ ‪1434/11/5‬ه املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ‪ ).....( /‬املســجل برقــم ‪ 34329653‬وتاريــخ‬\n‫‪1434/10/13‬ه ـ اخلــاص بدعــوى ‪ ).....(/‬بالوكالــة ضــد‪ ).....(/‬بشــأن‬\n‫قضيــة تلفــظ علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا باألكثريــة املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":201,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9e080fd1af16ffefa28d91f708ab3bc15a1345cfdc810ed9fdef27b1ded98315","normalized_text_hash":"dd14bd6a388458a45e279e82132d172d8cc86a877a9b7119a535efe09dd04f88","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p201-34329653"},{"id":"abcf30dd-65aa-5dd5-8721-b65d6693d0ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -تطاول املدعى عليه على املدعي -مطالبة املدعي مجازاة املدعى عليه جراء تطاوله -مصادقة املدعى عليه على الدعوى -ثبوت احلرمة والعقاب شرع ا -جلد املدعى عليه وأخذ التعهد بعدم العودة .","document_number":"33454757","case_number":"32315609","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/15","year":"1434","subject":"إيذاء الغير (حق خاص) -تطاول املدعى عليه على املدعي -مطالبة املدعي مجازاة املدعى عليه جراء تطاوله -مصادقة املدعى عليه على الدعوى -ثبوت احلرمة والعقاب شرع ا -جلد املدعى عليه وأخذ التعهد بعدم العودة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/15 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33454757 :‬‬\n                          ‫َر ْق ُم الدعوى‪32315609 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3425462‬تاريخه‪1434/01/28 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر (حــق خــاص)‪ -‬تطــاول املدعــى عليــه علــى املدعــي‪ -‬مطالبة‬\n       ‫املدعــي مجــازاة املدعــى عليــه جــراء تطاولــه‪ -‬مصادقــة املدعــى عليــه‬\n       ‫علــى الدعــوى‪ -‬ثبــوت احلرمــة والعقــاب شــرع ًا‪ -‬جلــد املدعــى عليــه‬\n                                                    ‫وأخــذ التعهــد بعــدم العــودة ‪.‬‬\n\n\n\n\n       ‫قولــه صلــى اهلل عليــه وســلم ( املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                            ‫ويــده ) ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي أن املدعــى عليــه يعمــل بإحــدى املكتبــات يف املســتودع‬\n       ‫وقــد حضــر إلــى املســتودع مــن أجــل شــراء كتــب وتفاجــأ أن املدعــى‬\n       ‫عليــه يصــرخ عليــه ويتطــاول بالــكالم وإذا به يلحــق به وزميله اآلخر إلى‬\n       ‫الســيارة وركــب الســيارة وحلــق بــه وحــاول فتــح بــاب الســيارة وركبــوا‬\n       ‫ســيارتهم وحلقــوا بــه وقامــوا بحــده وأجبــروه علــى الوقــوف بالقــوة ويطلــب‬\n       ‫مجازاتــه شــرعاً‪ -‬أنكــر املدعــى عليــه مــا جــاء بالدعــوى وقــال انــه حلــق‬\n       ‫باملدعــى عليــه بالســيارة مــن أجــل أن يطلــب حقــه فعليــه فواتيــر فوقــف‬\n       ‫مــن نفســه هكــذا أجــاب ‪ -‬ثــم جــرى االطــاع علــى القــرار الشــرعي‬\n       ‫فيمــا يتعلــق باحلــق العــام املتضمــن احلكــم بأخــذ التعهــد علــى املدعــى‬\n\n‫‪209‬‬\n\f‫عليــه ـ بنــاء علــى الدعــوى واإلجابــة ـ وحيــث صــادق املدعــى عليــه علــى‬\n‫الدعــوى وأقــر بلحاقــه للمدعــى ـ وحيــث مــا قــام بــه املدعــي عليــه فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ـ ولقولــه صلــى اهلل عليــه وســلم ( املســلم مــن‬\n‫ســلم املســلمون مــن لســانه ويــده ) ‪ -‬احلكــم بجلــد املدعــى عليــه عشــر‬\n‫جلــدات وأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا بــدر منــه ـ قــرر املدعــي‬\n‫القناعــة باحلكــم وقــرر املدعــى عليــه اعتراضــه علــى احلكــم بالئحــة‬\n‫اعتراضيــة فأفهــم بتعليمــات االســتئناف ـ صــدق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪32315609‬‬\n‫وتاريــخ ‪1432/07/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32962102‬وتاريــخ‬\n‫‪1432/07/27‬ه ـ ففــي يــوم االثنــن املوافق‪1433/11/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم وادعــى علــى احلاضــر معــه مصــري اجلنســية مبوجب‬\n‫االقامــة رقــم ‪ 209410388‬قائــا يف دعــواه يعمــل املدعــى عليــه مبكتبــة‬\n‫‪ ....‬يف املســتودع وقــد اشــتريت منــه عــدة كتــب عــن طريــق الهاتــف ويف‬\n‫يــوم ‪1431/3/15‬ه ـ حضــرت الــى املســتودع مــن اجــل شــراء كتــب‬\n‫وتفاجــأت بــه يصــرخ علــي ويتطــاول بالــكالم وخرجــت واذا بــه يلحق بي‬\n‫هــو وزميلــه إلــى الســيارة وركبــت الســيارة وحلقــوا بــي وحــاول علــي فتــح‬\n‫بــاب الســيارة وركبــوا ســيارتهم وحلقــوا بــي وقامــوا بحــدي واجبرونــي‬\n\n                                                                                          ‫‪210‬‬\n\f      ‫علــى الوقــوف بالقــوة لــذا اطلــب مجازاتــه شــرعا هــذه دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي بأنــه حضــر الــى‬\n      ‫املســتودع وأخــذ كتــاب مــن عنــدي وقــال لــي هــذا الســي دي ال يعمــل‬\n      ‫فقلــت إذا فتحتــه وعمــل ســتدفع ثمنــه قــال نعــم ففتحتــه وقمــت بتشــغيله‬\n      ‫فاشــتغل فقلــت لــه ادفــع قيمتــه فقــال ال فشــددت الــكالم معــه وبعدهــا‬\n      ‫خــرج وندمــت علــى الــذي حصــل وحلقــت بــه مــن أجــل أن اعتــذر وحلقــت بــه‬\n      ‫بالســيارة مــن اجــل ان اطلــب حقــي فعليــه فواتيــر فوقــف مــن نفســه هــذه‬\n      ‫إجابتــي هــذا وقــد جــرى االطــاع علــى القــرار الشــرعي رقــم ‪/4/308‬ج‬\n      ‫وتاريــخ ‪1431/06/26‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫اجلزئيــة ســابقا ‪ .........‬مبــا يتعلــق باحلــق العــام بأخــذ التعهــد علــى املدعــى‬\n      ‫عليــه فبنــاء علــى الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث صــادق‬\n      ‫املدعــى عليــه الدعــوى واقــر بلحاقــه للمدعــي وحيــث مــا قــام بــه املدعــي‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا ولقولــه صلــى اهلل عليــه وســلم «‬\n      ‫املســلم مــن ســلم املســلمون مــن لســانه ويــده « ولــكل مــا تقــدم فقــد‬\n      ‫حكمــت بجلــد املدعــى عليــه عشــر جلــدات واخــذ التعهــد عليــه بعــدم‬\n      ‫العــودة ملثــل مــا بــدر منــه وبذلــك حكمــت وبعــرض ذلــك علــى الطرفــن‬\n      ‫قــرر املدعــي القناعــة وقــرر املدعــى عليــه عــدم القناعــة واســتعد بتقــدمي‬\n      ‫الئحــة اعتراضيــة علــى احلكــم فأفهــم بــأن مــدة اإلعتــراض ثالثــون‬\n      ‫يومــا مــن تاريــخ احلكــم يف هــذا اليــوم اإلثنــن ‪1433/11/15‬ه ـ وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                 ‫يف ‪ 1433/11/15‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n      ‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n\n\n‫‪211‬‬\n\f‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بجــدة املســاعد رقــم ‪ 32/962102‬وتاريــخ‬\n‫‪1433/11/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫القاضــي باحملكمــة اجلزائيــة بجــدة رقــم ‪ 33454757‬وتاريــخ‬\n‫‪1433/11/15‬ه ـ احملكــوم فيــه مبــا دون بباطــن الصــك املتضمــن‬\n‫دعــوى ســعودي اجلنســية ضــد‪ /‬مصــري اجلنســية يف اعتــداء وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                          ‫وصحبــه وســلم‬\n\n\n\n\n                                                                           ‫‪212‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":209,"source_page_end":212,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0630634c8b6e369fd60cd490d4ffb1daa44b23485fe7da415feff53f7c936a44","normalized_text_hash":"e2bfd2706075ea83182992e39f661bb53271ed072f49738d8b2b79be7217872f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p209-33454757"},{"id":"ce84f269-de1f-583c-8081-ee2d1c0a0457","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتلفظ -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -شهادة الشاهدين بالواقعة- منشأ الدعوى ألفاظ املدعى عليه -إيجابية التقرير الطبي -إدانة","document_number":"34233705","case_number":"32452925","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتلفظ -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -شهادة الشاهدين بالواقعة- منشأ الدعوى ألفاظ املدعى عليه -إيجابية التقرير الطبي -إدانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/6/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34233705 :‬‬\n                         ‫َر ْق ُم الدعوى‪32452925 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34343097‬تاريخه‪1434/10 /28 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتلفــظ‪ -‬مطالبــة املدعــي‬\n      ‫باملجــازاة‪ -‬إنــكار املدعــى عليــه الدعــوى‪ -‬شــهادة الشــاهدين بالواقعــة‪-‬‬\n      ‫منشــأ الدعــوى ألفــاظ املدعــى عليــه ‪ -‬إيجابيــة التقريــر الطبــي ‪ -‬إدانــة‬\n                                                                      ‫املدعــى عليــه ‪.‬‬\n\n\n\n\n                                                      ‫اإلقرار حجة شرعية على املقر‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه احلاضــر معــه قــام بالتلفظ عليــه بألفاظ‬\n      ‫بذيئــة ثــم تشــابك معــه باأليــدي وضربــه بيــده وبعقــال ممــا تســبب يف‬\n      ‫إصابتــه بجــروح يف أنفــه ويــده وقدمــه‪ ،‬ولــذا فقــد طلــب احلكــم عليــه‬\n      ‫بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه تلفظــه علــى املدعــي‬\n      ‫وأقــر بحصــول ســوء تفاهــم بينهمــا أدى إلــى متاســك باأليــدي‪ -‬أحضــر‬\n      ‫املدعــي شــاهدين شــهدا مبــا يثبــت دعــواه وجــرى تعديلهمــا شــرعاً‪-‬‬\n      ‫املدعــى عليــه هــو مــن تســبب يف نشــوب هــذه املضاربــة بتلفظــه علــى‬\n      ‫املدعــي كمــا أنــه تســبب يف إصابتــه بجــرح مــدة شــفاءه املتوقعــة ثالثــة‬\n      ‫أيــام حســب التقريــر الطبــي‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا‬\n      ‫نســب إليــه وقــررت ســجنه ملــدة ثالثــة أيــام وأخــذ التعهــد عليــه بعــدم‬\n\n‫‪213‬‬\n\f‫العــودة ملــا بــدر منــه‪ -‬عــارض املدعــي واملدعــى عليــه علــى احلكــم‪-‬‬\n               ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫اجلزئيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ...../‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئية يف محافظة االحساء برقم ‪ 32452925‬وتاريخ ‪1432/10/15‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 321286953‬وتاريــخ ‪ 1432/10/15‬هـ حضر‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ) وادعــى علــى احلاضــر‬\n‫ا إننــي أعمــل‬  ‫معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم( ) قائـ ً‬\n‫وكيــل مدرســة مبتوســطة ‪ .........‬ب ـ ‪ .................‬ويف يــوم اإلثنــن املوافــق‬\n‫دخلت لغرفة املدرســن ألقوم بتكليف بعض املدرســن‬                   ‫ُ‬      ‫‪1432/6/26‬هـ‬\n‫يف احلصــص التــي ال يوجــد بهــا معلــم فقــال لــي األســتاذ هــذا احلاضــر‬\n‫معــي أريــد أن أطبــع أســئلة االختبــار عنــدك فقلـ ُـت لــه أخشــى أن يختــرب‬\n‫جهــازي ألن الفالشــات يوجــد بهــا فيروســات وليــس مــن عملــي طباعــة‬\n‫أســئلة املدرســن فقــال لــي أريــد الطابعــة فقــط فقلـ ُـت لــه قــد تكــون‬\n‫الطابعــة غيــر متعرفــة علــى جهــازك فقــال لــي (حقتــك حلــوة متعرفــة‬\n‫ـككت مــاذا يقصــد بهــذه العبــارة وقلـ ُـت لــه أنــت‬  ‫ُ‬          ‫علــى كل أحــد) فشـ‬\n‫فقلت‬\n ‫ُ‬      ‫رجــل كبيــر ال تتكلــم بهــذا الــكالم فقــال لــي الشــيب وال العيــب‬\n‫لــه أنــت لســت بكبيــر وال أديــب فقــال لــي مــا عليــك زود منكــم نســتفيد‬\n‫فضحــك املعلمــون احلاضريــن بالغرفــة فخرجـ ُـت ألداء عملــي ويف اليــوم‬\n‫التالــي وهــو يــوم الثالثــاء املوافــق ‪1432/6/27‬ه ـ دخــل املدعــي عليــه‬\n‫مكتبــي ومعــي املرشــد الطالبــي وبعــض الطــاب وكان يحمــل معــه‬\n\n                                                                                          ‫‪214‬‬\n\f      ‫حاســبه اآللــي والفــاش ميمــوري وطلــب طباعــة أســئلة االختبــار وألنهــا‬\n      ‫ســرية ومكتبــي بــه عــدد كبيــر مــن الطــاب فطلبـ ُـت منــه مرافقتي إلى‬\n      ‫املكتــب املجــاور لكــي يقــوم بطباعــة أســئلة االختبــار فلمــا دخلـ ُـت وإيــاه‬\n      ‫للمكتــب وحفاظ ـ ًا علــى ســرية األســئلة قمـ ُـت بإغــاق البــاب ثــم قلـ ُـت‬\n      ‫لــه يــا أســتاذ الــكالم البــذيء ال تتكلــم بــه مــرة أخــرى فنهرنــي وقــال‬\n      ‫أبعــد عنــي فدفعنــي ودفعتــه ثــم ضربنــي بعقالــه وضربتــه بــه ثــم ضربنــي‬\n      ‫علــى أنفــي وكان يف إصبــع يــده التــي ضربنــي بهــا خــامت كبيــر فصــه‬\n      ‫وضربنــي بــه علــى أنفــي وأدمانــي فتدافعـ ُـت وإيــاه ودفعنــي علــى زجــاج‬\n      ‫مرمــي علــى األرض فاجنرحــت قدمــي وتضاربـ ُـت أنــا وإيــاه ودفعنــي‬\n      ‫علــى اجلــدار ثــم التفــت وأخــذ مثلــث بالســتيكي يســتعمله مــدرس‬\n      ‫ـكت وإيــاه فانكســر املثلــث بيننــا فاجنرحــت يــدي‬        ‫الرياضيــات فتماسـ ُ‬\n      ‫اليســرى ومــن شــدة الســحب بينــي وبينــه جــرح رأســه ببقايــا املثلــث‬\n      ‫الــذي يف يــده ثــم دفعنــي وقــال لــي خــاص يــا شــيخ فتوقفـ ُـت وإيــاه‬\n      ‫عــن املضاربــة واتصــل علــى أحــد األســاتذة وقــد حضــر مديــر املدرســة‬\n      ‫وبعــض املدرســن وفتحـ ُـت بــاب املكتــب وقــد حــاول املديــر واحلاضريــن‬\n      ‫حــل املشــكلة لكــن دون فائــدة ومت ذهــاب كل واحــد منــا للمستشــفى‬\n      ‫أطلــب مجازاتــه لقــاء مــا بــدر منــه‪ ،‬وبعــرض الدعــوى علــى املدعــى عليــه‬\n      ‫ا ال صحــة ملــا ذكــره املدعــي يف دعــواه والصحيــح إننــي‬           ‫أجــاب قائ ـ ً‬\n      ‫أعمــل مــدرس رياضيــات مبتوســطة ‪ .........‬ب ـ ‪ .................‬ويف يــوم اإلثنــن‬\n      ‫املوافــق ‪1432/6/26‬ه ـ دخــل علينــا يف غرفــة املدرســن وكيل املدرســة‬\n      ‫هــذا احلاضــر معــي فطلبـ ُـت منــه طابعــة جهــازه احلاســب اآللــي ألمتكــن‬\n      ‫مــن طباعــة أســئلة االختبــار فقــال لــي إن طابعــة جهــازي قــد ال تتعــرف‬\n      ‫علــى كمبيوتــرك فقلـ ُـت لــه طابعتــك تتعــرف علــى أي جهــاز فقــال لــي‬\n\n\n‫‪215‬‬\n\f‫يالشــايب يالعايــب فقلـ ُـت لــه الشــيب وال العيــب فقــال لــي أنــت العيــب‬\n‫كلــه فقلـ ُـت لــه ومنــك نســتفيد ثــم انصــرف كل منــا يف حــال ســبيله‬\n‫ـرت‬‫ويف اليــوم التالــي وهــو يــوم الثالثــاء املوافــق ‪1432/6/27‬ه ـ حضـ ُ‬\n‫ملكتــب املدعــى عليــه ومعــي جهــاز احلاســب اآللــي وفــاش ميمــوري بهــا‬\n‫أســئلة االختبــار وطلبـ ُـت مــن املدعــى عليــه متكينــي مــن طباعــة األســئلة‬\n‫دخلت‬\n ‫ُ‬        ‫فطلــب منــي مرافقتــه إلــى مكتــب اإلدارة ولــم يكــن بــه أحــد وملــا‬\n‫معــه مكتــب اإلدارة أغلــق البــاب علينــا وأخــذ يتكلــم علـ ّـي بألفــاظ‬\n‫بذيئــة ويســبني ويشــتمني وأخــذ العقــال مــن رأســي وضربنــي بــه وأنــا‬\n‫أحــول تهدئتــه ولكــن دون فائــدة وأخــذ مثلــث بالســتيكي وضربنــي بــه‬\n‫علــى رأســي ممــا أدى إلــى إصابتــي وقــام بضربــي علــى اجلــدار فاتصلـ ُـت‬\n‫بأحــد املعلمــن بعــد أن ســقط علــى األرض وطلبـ ُـت مــن أحــد املعلمــن أن‬\n‫يحضــر إلينــا ليبعــده عنــي ثــم حضــر املديــر وبعــض املدرســن وطرقــوا‬\n‫البــاب عليــه حتــى فتــح البــاب ثــم ملــا دخلــوا علينــا أخــذ يســبني ويشــتمني‬\n‫ثــم مت أخــذي ملستشــفى احلــرس وهنــاك تلقيـ ُـت العــاج فليــس لــه حــق‬\n‫عنــدي بــل احلــق لــي عليــه وتوجــد لديكــم دعــوى لــي ضــده أطلــب بحقــي‬\n‫منــه يف اعتدائــه علـ ّـي وبــرد تلــك اإلجابــة علــى املدعــي قــال ال صحــه ملــا‬\n‫ذكــره املدعــى عليــه يف اجابتــه والصحيــح هــو مــا ذكرتــه يف دعــواي‬\n‫ولــدي بينــه واحضــر املدعــي للشــهادة كل مــن الســعودي بالســجل‬\n‫املدنــي برقــم ( ) والســعودي بالســجل املدنــي برقــم( ) وبســؤالهما عمــا‬\n‫لديهمــا مــن الشــهادة شــهد قائــا أشــهد بــاهلل العظيــم أنــه يف أحــد‬\n‫األيــام وبينمــا كنــت برفقــة املديــر أبلغنــا بوجــود مشــكلة بــن األســتاذ‬\n‫والوكيــل وعنــد ذهابنــا لهمــا وفتــح الغرفــة التــي كانــا فيهــا وجدناهمــا‬\n‫قــد تضاربــا مــع بعضهمــا والدمــاء تســيل منهمــا وحاولنــا الصلــح بينهمــا‬\n\n\n                                                                                        ‫‪216‬‬\n\f      ‫فطلبــا تأجيــل املوضــوع وقــد ذهــب برفقة للمستشــفى كمــا ذهب برفقة‬\n      ‫للمستشــفى وقمنــا بالتحقيــق يف املوضــوع مــع كل منهــم وســألناهم عــن‬\n      ‫أســباب تلــك املضاربــة فأفادونــا أنــه يف اليــوم الــذي قبــل املضاربــة ذهــب‬\n      ‫األســتاذ وهــو وكيــل شــئون الطــاب لغرفــة املدرســن إن لــدي فــاش‬\n      ‫ميمــوري وأرغــب اســتعمال الطابعــة التــي لديــك فقــال لــه األســتاذ رمبــا‬\n      ‫الطابعــة ال تتعــرف علــى الفــاش ميمــوري الــذي لديــك فقــال لــه حقتــك‬\n      ‫حلــوة وتتعــرف علــى كل شــيء فــرد عليــه األســتاذ الشــيب وال العيــب‬\n      ‫ا ومنكــم نســتفيد‬     ‫فقــال لــه األســتاذ أنــت العيــب كلــه فــرد عليــه قائـ ً‬\n      ‫ـدي مــن الشــهادة علمـ ًا بأننــي اعمــل وكيــل الشــئون اإلداريــة‬   ‫هــذا مــا لـ ّ‬\n      ‫ا لشــئون الطــاب واالســتاذ معلــم‬     ‫مبدرســة ‪ .................‬واالســتاذ وكيـ ً‬\n      ‫ا أشــهد بــاهلل العظيــم أنــه بعــد حصــول‬       ‫باملدرســة كمــا شــهد قائ ـ ً‬\n      ‫املضاربــة جــرى التحقيــق يف موضــوع املضاربــة بــن االســتاذ واالســتاذ مع‬\n      ‫االســاتذة كل مــن شــرف اخللــف وســؤالهم عــن أســباب تلــك املضاربــة‬\n      ‫فأفــادوا بــأن األســتاذ قــد دخــل غرفــة املدرســن وطلــب منــه االســتاذ‬\n      ‫ا إننــي أرغــب يف اســتعمال الطابعــة التــي لديــك فقــال لــه األســتاذ‬      ‫قائ ـ ً‬\n      ‫رمبــا الطابعــة ال تتعــرف علــى الفــاش ميمــوري الــذي لديــك فقــال لــه‬\n      ‫حقتــك حلــوة وتتعــرف علــى كل شــيء فقــال لــه االســتاذ وعايــب فــرد‬\n      ‫عليــه االســتاذ وال العيــب فقــال لــه االســتاذ انــت العيــب كلــه فــرد عليــه‬\n      ‫ـدي مــن الشــهادة علم ـ ًا بأننــي أعمــل‬\n                                               ‫ا ومنكــم نســتفيد هــذا مــا لـ ّ‬      ‫قائ ـ ً‬\n      ‫مرشــد طالبــي باملدرســة وبعــرض شــهادة الشــاهدين علــى املدعــى‬\n      ‫ا إن مــا جــاء يف شــهادة الشــاهدين علـ ّـي غيــر صحيــح‬      ‫عليــه أجــاب قائ ـ ً‬\n      ‫ـدي علــم إال أن املديــر هــو مــن قــام بالتحقيــق يف ذلــك املوضــوع‬  ‫وليــس لـ ّ‬\n      ‫فالشــاهدين لــم يكونــا موجديــن يف التحقيــق كمــا أن األســتاذ مــع‬\n\n\n‫‪217‬‬\n\f‫دخولــه هــو واملديــر يف تلــك الغرفــة التــي حصلــت فيهــا املشــكلة قــام‬\n‫املدعــي بســبي بقولــه لــي يــا حمــار كمــا أن مكتــب املدعــي الليلــي‬\n‫لــم يكــن مركــز لتصويــر األســئلة والتصويــر كان يف مكتــب املديــر‬\n‫النهــاري وبســؤال الشــاهدين عمــا ذكــره املدعــى عليــه أجــاب الشــاهد‬\n‫ا إن التحقيــق قــد حصــل مــن قبــل جلنــة مكونــة مــن ثالثــة أشــخاص‬       ‫قائـ ً‬\n‫أنــا أحدهــم ومديــر املدرســة واألســتاذ كمــا أن املدعــي لــم يقــل للمدعــى‬\n‫عليــه يــا حمــار وإمنــا أثنــاء دخولنــا وقــت املضاربــة علــى املدعــي واملدعــى‬\n‫عليــه ســمعنا املدعــي يقــول للمدعــى عليــه إن هــذا الــكالم ال يصــدر إال‬\n‫مــن احلمــارة ويقصــد بذلــك الكلمــة التــي قالهــا لــه املدعــى عليــه وهــي‬\n‫(حقتــك حلــوة تتعــرف علــى كل شــيء) كمــا أنــه مســموح التصويــر يف‬\n‫ا إن التحقيــق قــد حصــل‬     ‫املكتــب النهــاري أو الليلــي كمــا أجــاب قائـ ً‬\n‫مــن قبــل جلنــة مكونــة مــن ثالثــة أشــخاص أنــا أحدهــم ومديــر املدرســة‬\n‫ووكيــل املدرســة ا ٍألســتاذ كمــا أنــه مســموح التصويــر يف املكتــب‬\n‫ال مــن‬\n      ‫النهــاري أو الليلــي كمــا أحضــر املدعــي لتزكيــة الشــاهدين ك ً‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ) ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬وأضــاف املدعــي قائــا أود أن أوضــح‬\n‫لفضيلتكــم بأننــي إمــام مســجد منــذ خمــس عشــرة ســنه وأنــا اآلن إمــام‬\n‫مســجد ‪ .........................‬منــذ عــام ‪1417‬ه ـ كمــا أننــي مــدرس دراســات‬\n‫إســامية منــذ ثــاث عشــره ســنه وقبلهــا كنــت إمــام وواعــظ بالشــؤون‬\n‫الدينيــة باحلــرس الوطنــي منــذ عــام ‪1409‬ه ـ وأنــا حافــظ لكتــاب اهلل‬\n‫واهلل احلمــد واملنــة منــذ عــام ‪1412‬ه ـ كمــا أننــي تخرجــت مــن معهــد‬\n‫احلــرم املكــي عــام ‪1417‬ه ـ ومتخــرج مــن قســم الشــريعة بكليــة‬\n‫الشــريعة باإلحســاء عــام ‪1421‬ه ـ ولــي اآلن دروس ومحاضــرات بســجن‬\n\n\n                                                                                        ‫‪218‬‬\n\f      ‫اإلحســاء وكان حاضــرا املدعــي العــام فجــرى عــرض هــذه الدعــوى‬\n      ‫عليــه فقــال إننــي ال أرغــب يف إقامــة دعــوى عامــة علــى املدعــى عليــه‬\n      ‫يف الوقــت احلالــي ألننــي غيــر مخــول مــن مرجعــي لــذا وبعــد ســماع‬\n      ‫الدعــوى واإلجابــة وحيــث طلــب املدعــي مجــازاة املدعــى عليــه لتلفظــه‬\n      ‫عليــه واعتدائــه بالضــرب والتســبب يف إصابتــه وإن املدعــى عليــه قــد‬\n      ‫أقــر بحصــول ســوء تفاهــم بينهمــا أدى ذلــك إلــى التماســك باأليــدي وإن‬\n      ‫اإلقــرار حجــة شــرعية علــى املقــر وإن املتأمــل لهــذه القضيــة يجــد أن‬\n      ‫منشــأها هــو مــا تلفــظ بــه املدعــى عليــه علــى املدعــي وإن البينــة املوصلــة‬\n      ‫واملعدلــة التعديــل الشــرعي قــد أثبتــت ذلــك وإن مــدة شــفاء املدعــي قــد‬\n      ‫حــددت مــن يومــن إلــى ثالثــة أيــام وذلك حســبما أوضحــه التقرير الطبي‬\n      ‫الصــادر مــن مستشــفى امللــك عبدالعزيــز باحلــرس الوطنــي باألحســاء‬\n      ‫برقــم (‪ )53525‬تاريــخ ‪2011/11/22‬م وإنــه ال ســوابق علــى املدعــى‬\n      ‫عليــه وحيــث إن للمدعــى عليــه هنــا دعــوى ضــد املدعــي يف هــذه القضيــة‬\n      ‫يطالــب مبجازاتــه العتدائــه عليــه بالضــرب وقــد حكــم علــى املدعــى‬\n      ‫عليــه يف جلســتها التــي قبــل هــذه اجللســة مباشــرة لــذا فقــد تقــرر مــا‬\n      ‫يلــي أوال ثبــوت إدانــة املدعــى عليــه لتلفظــه علــى املدعــي واعتدائــه عليــه‬\n      ‫بالضــرب وتعزيــره لقــاء ذلــك بســجنه ثالثــة أيــام تبــدأ مــن تاريــخ إيقافــه‬\n      ‫بســبب هــذه القضيــة ال ينفــذ ذلــك الســجن إال بحضــور املدعــي ويســقط‬\n      ‫بإســقاطه أو بعضــه ثانيــا أخــذ التعهــد الــازم عليــه بعــدم العــودة ملثــل‬\n      ‫مــا بــدر منــه مســتقبال وبذلــك كلــه حكمــت يف احلــق اخلــاص وبعرضــه‬\n      ‫اعتــرض عليــه املدعــي واملدعــى عليــه وكالــه وطلبــا تقــدمي الئحــة‬\n      ‫اعتراضيــة فجــرى إفهامهمــا بأنــه ســوف يتــم تســليمه صــورة مــن القــرار‬\n      ‫الشــرعي يــوم غــدا األربعــاء ‪1434/6/7‬ه ـ وإن لهمــا مــدة ثالثــن يوم ـ ًا‬\n\n\n‫‪219‬‬\n\f‫تبــدأ مــن تاريــخ اســتالمهما بعدهــا يســقط حقهمــا يف تقــدمي الالئحــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/6/6‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/08/28‬ه ـ حيــث‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية واملتعلقــة‬\n‫بدعــوى ضــد وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة‬\n‫األولــى رقــم (‪ )34288614‬تاريــخ ‪14324/8/6‬ه ـ املتضمــن أوال‬\n‫فضيلتــه أشــار إلــى وجــود حكــم علــى املدعــي يف دعــوى أقامهــا املدعــى‬\n‫عليــه ولــم جنــد أن فضيلتــه أطلــع علــى هــذا الصــك وأرفــق صــورة منــه‬\n‫ثانيــا املدعــى عليــه اعتــرض علــى احلكــم ولــم جنــد أن فضيلتــه ســلم‬\n‫لــه صــورة مــن القــرار وقــد احلــق يف صــورة الضبــط انــه قــدم الئحــة‬\n‫اعتراضيــة يف ‪1434/7/22‬ه ـ مــع انــه لــم يســلم لــه صــورة مــن احلكــم‬\n‫ثالثــا املدعــي جــرى تســليمه صــورة مــن القــرار ولــم يكمــل الــازم بعــد‬\n‫ذلــك رابعــا فضيلتــه اثبــت إدانــة املدعــى عليــه بالضــرب للمدعــي فهــل‬\n‫ذلــك مــن املدعــى عليــه ابتــدأ أم دفاعــا ولوجاهــة مــا ارتــأوه أصحــاب‬\n‫الفضيلــة فأجيــب أوال بالنســبة للمالحظــة األولــى جتــدون صــورة مــن‬\n‫القــرار املصــدق عليــه مــن قبــل قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية فيمــا يتعلــق بدعــوى املدعــي عليــه هنــا‬\n‫ضــد املدعــي أمــا بالنســبة للمالحظــة الثانيــة والثالثــة فقــد مت تســليم‬\n‫املدعــى عليــه واملدعــي صــورة مــن القــرار حيــث إن كال منهمــا قــدم‬\n‫الئحتــه االعتراضيــة إال أن الكاتــب لــم يثبــت ذلــك يف الضبــط حســب‬\n‫املتبــع وهــذا ســهوا منــه وســوف يتــم تــدارك مثــل هــذا مســتقبال إن شــاء‬\n‫اهلل تعالــى أمــا املالحظــة الرابعــة فــإن هــذه القضيــة مضاربــة وقعــت بــن‬\n\n\n                                                                                    ‫‪220‬‬\n\f      ‫املدعــى عليــه واملدعــي ومثــل هــذه القضايــا يصعــب حتديــد املبتــدئ‬\n      ‫بتلــك املضاربــة حيــث إنــه يدعــي كل منهمــا ان صاحبــه هــو مــن ابتــدأ‬\n      ‫بتلــك املضاربــة ولــذا فقــد نظرنــا قضيتــن يف هــذه املضاربــة أحدهمــا يف‬\n      ‫القضيــة األولــى مــدع ويف القضيــة الثانيــة مدعــى عليــه واآلخــر مثلــه وقد‬\n      ‫صدقــت القضيــة األولــى حســبما يتضــح ألصحــاب الفضيلــة مــن صــورة‬\n      ‫الصــك املرفــق وهــذه هــي القضيــة الثانيــة لــذا فاإلجــراء مــا تقــدم وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                ‫حــرر يف ‪1434/8/28‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنا نحن قضــاة الدائرة اجلزائية األولى‬\n      ‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف الشــيخ‬\n      ‫د‪ ................ .‬برقــم ‪ 1747050/34‬وتاريــخ ‪1434/9/3‬ه املقيــدة لــدى‬\n      ‫احملكمــة برقــم ‪ 342159721‬وتاريــخ ‪1434/9/10‬ه املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلتــه املســجل برقــم ‪ 34233705‬وتاريــخ ‪1434/6/7‬ه‬\n      ‫اخلــاص بدعــوى‪ ............... /‬ضــد‪ ................. /‬يف قضيــة شــتم وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬حيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه والالئحتــن االعتراضيتــن وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم ‪ 34288614‬يف ‪1434/8/6‬ه قررنــا املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                             ‫حــرر يف ‪1434/10/25‬هــ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":213,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ec54786da93cdf2bdc049f0fa9864e996619f5736d156dbc78c8205185a07c9b","normalized_text_hash":"af2ae85d81c0b18f33b8605c9998e38ec6cbc35e4452d515387867ef388d5eed","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p213-34233705"},{"id":"fd862150-021f-5e60-904a-6c3278eed37b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -باغ كيدي تسبب يف السجن -مطالبة املدعي بتعزير املدعى عليه -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"33361564","case_number":"32597663","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة 222 على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/29","year":"1434","subject":"إيذاء الغير (حق خاص) -باغ كيدي تسبب يف السجن -مطالبة املدعي بتعزير املدعى عليه -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33361564 :‬‬\n                   ‫َر ْق ُم الدعوى‪32597663 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 33428858‬تاريخه‪1433/10/17 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬بــاغ كيــدي تســبب يف الســجن‪ -‬مطالبــة‬\n‫املدعــي بتعزيــر املدعــى عليــه‪ -‬بينــة املدعــي غيــر موصلــة‪ -‬ميــن املدعــى‬\n                                  ‫عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n    ‫قول النبي صلى اهلل عليه وسلم‪( :‬ولكن اليمني على املدعى عليه)‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه قــدم ضــده بالغــا ملركــز الشــرطة بأنــه‬\n‫أشــهر الســاح يف وجهــه فتــم إيقافــه علــى إثــر ذلــك ملــدة يــوم واحــد إال‬\n‫أن املدعــى عليــه لــم يتمكــن مــن إثبــات ذلــك ضــده‪ ،‬ولــذا فقــد طلــب‬\n‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه بأنــه قــدم‬\n‫بالغــا ضــد املدعــي ودفــع بأنــه فعــل ذلــك بســبب تهديــده لــه وألختــه‬\n‫وقيامــه بضربهــا‪ ،‬كمــا أنكــر أن يكــون ذلــك البــاغ هــو الســبب يف‬\n‫توقيفــه‪ -‬اطلعــت احملكمــة علــى ملــف القضيــة فلــم جتــد فيــه مــا يثبــت‬\n‫دعــوى املدعــي‪ -‬طلــب املدعــي ميــن خصمــه علــى نفــي دعــواه فأداهــا‬\n‫طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعــي جتــاه املدعــى عليــه لعــدم ثبــوت موجبهــا‪ -‬قنــع املدعــى عليــه‬\n‫باحلكــم وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n\n                                                                                     ‫‪222‬‬\n\f                                                                        ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ .‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائية يف محافظة االحساء برقم ‪ 32597663‬وتاريخ ‪1432/12/23‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 321610827‬وتاريــخ ‪1432/12/23‬ه ـ ففــي‬\n      ‫هــذا اليــوم الســبت املوافق‪1433/02/27‬ه ـ فتحــت اجللســة الســاعة‬\n      ‫‪ 11 :00‬وفيهــا حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..........‬وادعــى علــى الغائــب عــن اجللســة قائــا لقــد ســبق أن تقــدم‬\n      ‫عــن اجللســة ببــاغ ضــدي بأننــي أشــهرت الســاح يف وجهــه ولــم يثبــت‬\n      ‫ذلــك وقــد ترتــب علــى ذلــك ســجني مبركــز شــرطة الصاحليــة ملــده يــوم‬\n      ‫واســائه لســمعتي اطلــب مجازاتــه لقــاء ذلــك ولعــدم حضــور املدعــى عليــه‬\n      ‫جــرى تأجيــل اجللســة ويف يــوم االثنــن املوافق‪1433/05/10‬ه ـ حضــر‬\n      ‫املدعــي واملدعــى عليــه ‪ ...........‬ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫‪ ..........‬وبعــرض دعــوى املدعــي علــى املدعــى عليــه أجــاب قائــا ال صحــه‬\n      ‫ملــا ذكــره املدعــي يف دعــواه والصحيــح أن املدعــي هــو شــقيقي األكبــر‬\n      ‫وتوجــد بينــي وبينــه قضايــا كثيــره يف هــذه احملكمــة لــدى أربعــة‬\n      ‫مكاتــب قضائيــة وأمــا القضيــة التــي يذكرهــا يف دعــواه إنــه حصــل‬\n      ‫ســوء تفاهــم بينــي وبينــه قــام علــى أثــره بتهديــدي بأنــه ســوف يطلــق علــي‬\n      ‫وعلــى أختــي ‪ ......‬وإنــه قــام بضربهــا ضربــا مبرحا وألنه يعمــل بالدوريات‬\n      ‫األمنيــة فتقدمــت بشــكوى ضــده ملركــز شــرطة الصاحليــة وملــا ســألني‬\n      ‫احملقــق هــل رأيــت ســاح بيــد املدعــي عندمــا هــددك فقلــت إننــي رأيــت‬\n\n‫‪223‬‬\n\f‫شــيئا أســود يف يــده وال أعلــم مــا هــو لكننــي ظننتــه مســدس ألنــه قــال‬\n‫ســيطلق علــي وعلــى اختــي ‪ ......‬ويقتلنــا ثــم ملــا نصحنــي احملقــق تنازلــت‬\n‫عنــه يف تلــك الليلــة لكنــه ســجن ألنه ضرب اختي ضربــا مبرحا واتهمته‬\n‫بأنــه اخــذ منهــا اغراضــا فســجنه ليــس ألننــي اتهمتــه بأنــه اشــهر ســاح‬\n‫علــي وإمنــا بســبب ضربــه ألختــي واتهامهــا لــه لــذا فليــس لــه حــق عنــدي‬\n‫وبــرد ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه يف دعــواي وامــل مــن‬\n‫فضيلتكــم الكتابــة لشــرطة الصاحليــة ألفادتكــم عــن صحــة ذلــك لــذا‬\n‫وحيــث االمــر مــا ذكــر فقــد امرنــا بالكتابة لشــرطة الصاحليــة ألفادتنا‬\n‫مبــا لديهــم يف هــذه القضيــة وتزويدنــا بصــوره مــن ملــف القضيــة وجــرى‬\n‫تأجيــل اجللســة ويف يــوم الثالثــاء املوافــق ‪1433/7/29‬ه ـ حضــر املدعــي‬\n‫واملدعى عليه وكان ســبق أن كتبنا ملركز شــرطة الصاحلية بخطابنا‬\n‫رقــم ‪ 33/881207‬وتاريــخ ‪1433/5/18‬ه وخطابنــا رقــم ‪33/989029‬‬\n‫وتاريــخ ‪1433/6/2‬ه ـ إلفادتنــا عــن صحــة مــا ذكــره املدعــي مــن إن‬\n‫املدعــى عليــه قــد تســبب يف ســجنه بســبب اتهامــه للمدعــي بأنــه قــد‬\n‫هــدده مبســدس وإفادتنــا كــم مــدة ســجنه والســبب يف ســجنه فوردنــا‬\n‫خطاب مدير شــرطة محافظة االحســاء برقم ‪/9/21‬ص‪ 4240/‬وتاريخ‬\n‫‪1433/6/4‬ه ـ ونــص احلاجــة منــه ( عليــه نفيدكــم بــأن املذكــور قــد مت‬\n‫إيقافــه لدينــا علــى ذمــة قضيــة مضاربــه بتاريــخ ‪1431/10/4‬ه ـ وأفــرج‬\n‫عنــه بتاريــخ ‪1433/10/5‬ه ـ وصــدر بحقــه يف القضيــة القــرار الشــرعي‬\n‫رقــم ‪ 4/119‬يف ‪1432/7/2‬ه ـ املتضمــن تعزيــره بالســجن خمســة أيــام‬\n‫وجلــده ثالثــن جلــدة ومت إنفــاذ املقــرر شــرعا ) أ ‪ .‬ه ـ وبعــرض ذلــك علــى‬\n‫املدعــي واملدعــى عليــه قــررا قناعتهمــا مبــا جــاء فيــه وقــال املدعــي إننــي‬\n‫اطلــب مــن املدعــى عليــه إن يحلــف بــاهلل العظيــم بأنــه لــم يتســبب يف‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫ســجني فــإن هــو حلــف فــا أطالبــه بشــيء بخصــوص هــذه الدعــوى‬\n      ‫وبعــرض ذلــك علــى املدعــى عليه اســتعد بــأداء اليمني وأداهــا قائال واهلل‬\n      ‫العظيــم إننــي لــم أتســبب يف ســجن أخــي هــذا احلاضــر معــي وإمنــا تســبب‬\n      ‫يف ســجنه هــو لضربــه شــقيقتي وقــد جــرى منــا مناصحــة الطرفــن ملــا‬\n      ‫بينهمــا مــن قرابــة ولكــن املدعــي أصــر علــى مجــازات املدعــى عليــه‬\n      ‫لــذا وبعــد ســماع الدعــوى واإلجابــة وان املدعــى عليــه قــد أنكــر ذلــك‬\n      ‫وذكــر بــان الســبب يف ســجنه هــو العتدائــه علــى أختــه وليــس بســببه‬\n      ‫وإن مركــز الشــرطة املختــص قــد ذكــر بــأن الســبب يف ســجن املدعــي‬\n      ‫هــو العتدائــه علــى أختــه وليــس بســبب اتهــام املدعــى عليــه للمدعــي وإن‬\n      ‫املدعــي قــد طلــب ميــن خصمــه علــى نفــي دعــواه وإن املدعــى عليــه قــد‬\n      ‫اســتعد بــأداء وإن املدعــى عليــه قــد اســتعد بــأداء اليمــن وأداهــا ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم ( ولكــن اليمــن علــى املدعــى عليــه ) وملــا هــو‬\n      ‫مقــرر شــرعا بــأن اليمــن تقطــع اخلصومــة يف احلــال لــذا فقــد حكمــت‬\n      ‫بصــرف النظــر عــن طلــب املدعــي يف مجــازات املدعــى عليــه لعــدم ثبــوت‬\n      ‫موجبــه وبعرضــه قــرر املدعــى عليــه قناعتــه بــه أمــا املدعــي فاعتــرض‬\n      ‫عليــه وطلــب تقــدمي الئحــة اعتراضيــه فأفهمنــاه بــأن لــه مــدة شــهر تبــدأ‬\n      ‫مــن تاريــخ اليــوم وبعدهــا يســقط حقــه يف تقــدمي الئحــة اعتراضيــه‬\n      ‫ويكتســب احلكــم القطعيــة ففهــم ذلــك بحضــور وشــهادة كال مــن‬\n      ‫جنــدي احملكمــة وموظــف املكتــب وأقفلــت اجللســة الســاعة العاشــرة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‬\n                                                            ‫حــرر يف ‪1433/7/29‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ‬\n      ‫وكانــت قــد وردتنــا املعاملــة مــن محكمة االســتئناف باملنطقة الشــرقية‬\n\n\n‫‪225‬‬\n\f‫واملتعلقــة بدعــوى وبرفقهــا القــرار الصــادر مــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة رقــم ‪ 33428858‬وتاريــخ ‪1433/10/17‬ه ـ املتضمــن أنــه لوحــظ‬\n‫أن املدعــي اعتــرض علــى احلكــم ولــم ترفــق لــه الئحــة ولــم يذكــر شــيء‬\n‫بخصــوص االعتــراض والبــد مــن ذلــك وجوابـ ًا عــن ذلــك فــإن املذكــور‬\n‫املعتــرض علــى احلكــم قــد رفــض التوقيــع علــى الضبــط فتــم إفهامــه‬\n‫بأنــه ســوف يســقط حقــه يف تقــدمي الالئحــة االعتراضيــة وبالفعــل أعطــي‬\n‫مــدة شــهر ولــم يوقــع علــى الضبــط كمــا لــم يقــدم الئحــة اعتراضيــة‬\n‫عليــه وقــد أوضحنــا ذلــك عنــد تــاوة احلكــم عليــه لــذا فاإلجــراء مــا‬\n‫تقــدم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪1433/11/24‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":222,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a711beb4d294a179abb104543031f696d7cd0f8dc9ebd64bb6fbd57df8268e55","normalized_text_hash":"9806583629015ea4a761f5dd3ff3c1e402bca87852c13f3e1bd040097930249b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p222-33361564"},{"id":"00c70cd6-9381-57c8-b3cd-33bbc37ca079","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء غير -سب وتلفظ -طلب تعزير املدعى عليه لقاء تلفظه -إقرار املدعى عليه -املسلم من سلم املسلمون من لسانه ويده - تعذر الصلح بن الطرفن -تعزير املدعى عليه باجللد لقاء تلفظه","document_number":"34168835","case_number":"33131997","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"إيذاء غير -سب وتلفظ -طلب تعزير املدعى عليه لقاء تلفظه -إقرار املدعى عليه -املسلم من سلم املسلمون من لسانه ويده - تعذر الصلح بن الطرفن -تعزير املدعى عليه باجللد لقاء تلفظه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34168835 :‬‬\n                         ‫َر ْق ُم الدعوى‪33131997 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34246763‬تاريخه‪ 1434/06/20 :‬هـ‬\n\n\n      ‫إيــذاء غيــر ‪ -‬ســب وتلفــظ ‪ -‬طلــب تعزيــر املدعــى عليــه لقــاء تلفظــه‬\n      ‫‪ -‬إقــرار املدعــى عليــه ‪ -‬املســلم مــن ســلم املســلمون مــن لســانه ويــده ‪-‬‬\n      ‫تعــذر الصلــح بــن الطرفــن ‪ -‬تعزيــر املدعــى عليــه باجللــد لقــاء تلفظــه‬\n                                                                     ‫علــى املدعــي ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                                ‫ومالــه وعرضــه ) ‪.‬‬\n      ‫‪ .2‬قوله صلى اهلل عليه وســلم ‪ ( :‬املســلم من ســلم املســلمون من لســانه‬\n                                                                          ‫و يــده ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليــه بأنــه قــام بســبه والتلفــظ عليــه و يطلــب‬\n      ‫تعزيــره لذلــك ـ صــادق املدعــى عليــه علــى دعــوى املدعــي وذكــر أن‬\n      ‫املدعــي عليــه لــه قضايــا كثيــرة يف احملاكــم فقلــت لــه ‪( :‬خــاف اهلل)‬\n      ‫ثــم رد عليــه بألفــاظ بذيئــة ال يذكرهــا ثــم تلفــظ عليــه بألفــاظ بذيئــة‬\n      ‫ال يذكرهــا ثــم ذكــر أنــه ســريع الغضــب ويصــدر منــه مــا ال يرتضيــه‬\n      ‫ويراجــع يف العيــادات النفســية ولديــه تقاريــر طبيــة يف انفعاالتــه ـ أبــرز‬\n      ‫املدعــى عليــه تقريــر ًا طبي ـ ًا مــن مستشــفى الصحــة النفســية أشــير إلــى‬\n\n‫‪227‬‬\n\f‫رقمــه وتاريخــه يتضمــن أن املدعــى عليــه لديــه اضطــراب وجدانــي‬\n‫كمــا أبــرز تقريــر ًا صــادر ًا مــن مستشــفى آخــر بــدون رقــم وتاريــخ‬\n‫مكتوب ـ ًا باللغــة اإلجنليزيــة ـ قــرر املدعــى عليــه أنــه ال يطالــب املدعــي‬\n‫بخصــوص تلفظــه عليــه بشــيء ـ وبعــرض ذلــك علــى املدعــي أنكــر مــا‬\n‫ذكــره املدعــى عليــه مــن تلفظــه علــى املدعــى عليــه بــأي لفــظ مشــن ـ‬\n‫جــرى عــرض الطرفــن علــى جلنــة الصلــح وقــد تعــذر اإلصــاح بينهمــا ـ‬\n‫ونظــر ًا ألن تلفــظ املدعــى عليــه علــى املدعــي بألفــاظ بذيئــة فعــل محــرم‬\n‫شــرع ًا يســتحق العقــاب عليــه ـ ونظــر ًا لقولــه صلــى اهلل عليــه وســلم ‪:‬‬\n‫(كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه ) وإلقــرار املدعــى‬\n‫عليــه بتلفظــه علــى املدعــي ـ ونظــر ًا حلالــة املدعــى عليــه النفســية وحيــث‬\n‫تعــذر الصلــح بــن الطرفــن ـ صــدر احلكــم بتعزيــر املدعــى عليــه باجللــد‬\n‫عشــرين جلــدة دفعــة واحــدة وأخــذ التعهــد عليــه بلــزوم االســتقامة وعــدم‬\n‫العــودة ملــا بــدر منــه ـ قــرر املدعــي القناعــة وقــرر املدعــى عليــه اعتراضــه‬\n‫علــى احلكــم بالئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف ـ صــدق‬\n                                         ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪ 33131997‬وتاريــخ‬\n‫‪ 1433/02/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33344842‬وتاريــخ‬\n‫‪ 1433/02/21‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي‪ ....... /‬ســعودي اجلنســية‬\n\n                                                                                         ‫‪228‬‬\n\f      ‫حامــل الســجل املدنــي رقــم ( ‪ ) .......‬وحضــر حلضــوره املدعــى عليــه‪/‬‬\n      ‫‪ .......‬ســعودي اجلنســية حامــل الســجل املدنــي رقــم ( ‪ ) .......‬وقــرر املدعــي‬\n      ‫دعــواه قائــا أننــي كنــت متواجــدا يف أحــد محــات إصــاح اإلطــارات‬\n      ‫مبحافظــة ‪ ...‬وأثنــاء ذلــك حضــر املدعــى عليــه واســتقبلته للســام عليــه‬\n      ‫وال توجــد بينــي وبينــة معرفــة ملحــة وبادرنــي قائــا أنــت ‪ .......‬؟ فقلــت‬\n      ‫لــه نعــم فقــال (والتــراب وراك تشــكي ‪ .......‬فقلــت لــه صــل علــى النبــي‬\n      ‫فقــال اهلل يلعنــك ويلعــن أبــوك وجــدك وإذا لزمتــك انــي ال طــي يف‬\n      ‫بطنــك ) أطلــب تعزيــر املدعــى عليــه لقــاء تلفظــه بالســجن أو اجللــد هــذه‬\n      ‫ا لقــد حضــرت‬   ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫للمدعــي كمــا ذكــره بدعــواه وملــا علمــت أنــه هــو ‪ .......‬قلــت لــه خــاف‬\n      ‫اهلل وذكرتــه بــاهلل حيــث إن للمدعــي دعــاوي كثيــرة يف احملاكــم‬\n      ‫وخصوصــا يف محكمــة ‪ ...‬ثــم رد علــي بألفــاظ بذيئــة ال أذكرهــا ثــم‬\n      ‫تلفظــت عليــه أنــا أيضــا بألفــاظ بذيئــة ال أتذكرهــا وأنــا رجــل ســريع‬\n      ‫الغضــب ويصــدر منــي حــال الغضــب مــا ال أرتضيــه والقضيــة مضــى‬\n      ‫عليهــا مايزيــد علــى الســنة فــا أتذكــر ماقلتــه لــه مــن ألفــاظ علــى‬\n      ‫وجــه التحديــد وأنــا أراجــع العيــادات النفســية ولــدي تقاريــر طبيــة يف‬\n      ‫إنفعاالتــي هكــذا أجــاب ثــم أبــرز املدعــى عليــه أصــل التقريــر الطبــي‬\n      ‫رقــم ( ‪ ) .......‬وتاريــخ ‪1433/6/2‬ه ـ الصــادر مــن مستشــفى الصحــة‬\n      ‫النفســية بالطائــف املتضمــن أن لــدى املدعــى عليــه إضطــراب وجدانــي‬\n      ‫كمــا أبــرز أصــل تقريــر طبــي صــادر مــن مجموعــة مستشــفيات ‪...‬‬\n      ‫بــدون رقــم وبــدون تاريــخ وقــد كتــب باللغــة اإلجنليزيــة وأضــاف املدعــى‬\n      ‫عليــه قائــا أننــي ال أطالــب املدعــي بخصــوص تلفظــة علــي بشــئ البتــة‬\n      ‫هكــذا أجــاب وبعــرض ماقــرره املدعــى عليــه علــى املدعــي أجــاب قائــا‬\n\n\n‫‪229‬‬\n\f‫أننــي لــم أتلفــظ عليــه بــأي لفــظ مشــن البتــة هكــذا أجــاب فبنــاء‬\n‫علــى ماتقــدم مــن الدعــوى واألجابــة وإلقــرار املدعــى عليــه بتلفظــه‬\n‫علــى املدعــي بألفــاظ بذيئــة ولقــول النبــي صلــى اهلل عليــه وســلم (كل‬\n‫املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه ) ولقولــه عليــه الســام‬\n‫(املســلم مــن ســلم املســلمون مــن لســانه ويــده) ومبــا أن تلفــظ املدعــى‬\n‫عليــه علــى املدعــي بألفــاظ بذيئــة فعــل محــرم شــرعا يســتحق العقــاب‬\n‫عليــه ونظــرا حلــال املدعــى عليــه النفســية وحيــث جــرى عــرض الطرفــن‬\n‫علــى جلنــة اإلصــاح بهــذة احملكمــة بخطابنــا رقــم ‪ )33344872‬وتاريــخ‬\n‫‪1434/2/3‬ه ـ وقــد تعــذر اإلصــاح بينهمــا فلمــا ســبق فقــد ثبــت لــدي‬\n‫تلفــظ املدعــى عليــه علــى املدعــي بألفــاظ بذيئــة وحكمــت علــى املدعــى‬\n‫عليــه تعزيــرا مبــا يلــي أوال ‪ :‬يجلــد املدعــى عليــه ‪ ....... /‬عشــرين جلــدة‬\n‫دفعــة واحــدة ثانيــا ‪ :‬يؤخــذ التعهــد علــى املدعــى عليــه بلــزوم اإلســتقامة‬\n‫وعــدم العــودة ملابــدر منــه وبعــرض احلكــم علــى الطرفــن قــررا ملدعــي‬\n‫قناعتــة كمــا قــرر املدعــى عليــه عــدم قناعتــة طالبــا رفعــه حملكمــة‬\n‫اإلســتئناف مــع تقــدمي الئحــة إعتراضيــة عليــه فأفهمتــه بــأن لــه إســتالم‬\n‫نســخة مــن احلكــم يف هــذا اليــوم األحــد ‪1434/3/22‬ه ـ وأن مهلــة‬\n‫اإلعتــراض علــى احلكــم وقدرهــا ثالثــون يومــا ســوف حتســب إعتبــارا‬\n‫مــن تاريــخ هــذا اليــوم فــإن مضــت املــدة دون تقــدمي اعتراضــه فــإن حقــه‬\n‫يف تقــدمي االعتــراض عليــه يكــون ســاقطا وعلــى ذلــك جــرى التوقيــع‬\n‫وكان ختــام اجللســة الســاعة احلاديــة عشــرة صباحــا وبــاهلل التوفيــق‬\n                                         ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/04/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة صباحــا فبنــاء علــى انتهــاء مهلــة‬\n\n\n                                                                                     ‫‪230‬‬\n\f      ‫االعتــراض حيــث أفهــم املدعــى عليــه بــأن لــه مهلــة ثالثــن يومــا اعتبــارا‬\n      ‫مــن تاريــخ ‪1434/03/22‬ه ـ لتقــدمي اعتراضــه وعليــه فقــد ســقط حــق‬\n      ‫املدعــى عليــه يف تقــدمي الئحتــه اإلعتراضيــة وأمــرت برفــع احلكــم‬\n      ‫حملمــة اإلســتئناف مبكــة املكرمــة لتدقيقــة ولئــا يخفــى جــرى أثباتــه‬\n      ‫وكان ختــام اجللســة الســاعة الثامنــة والنصــف صباحــا وبــاهلل التوفيــق‬\n                   ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                 ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة رقــم(‪)33828246‬‬\n      ‫وتاريخ(‪1434/6/11‬هــ) املرفــق بهــا الصــك رقــم(‪)34168835‬‬\n      ‫وتاريخ(‪1434/3/22‬هـ)الصــادر مــن فضيلــة الشــيخ‪ ....... /‬القاضــي‬\n      ‫باحملكمــة اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى‪ ....... /‬ســعودي اجلنســية‬\n      ‫ضــد‪ ، ....... /‬املتهــم يف التلفــظ بألفــاظ بذيئــة احملكــوم فيــه مبــا‬\n      ‫دون باطنــه ‪ ، ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                        ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪231‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":227,"source_page_end":231,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38caf7d3ef19de8e425160ec1c2386badbaf6715957b9116512a2336c9fce0ee","normalized_text_hash":"3c7321e35f9751a9941238b541853c746dac343ac51b9a6fe10931946b85e228","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p227-34168835"},{"id":"aab98a11-8bd0-55b6-8aab-d59a7721fc96","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة - حق املدعي يف قبول أو عدم قبول مين املدعى عليه بنفي الدعوى","document_number":"33470723","case_number":"33207246","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/30","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة - حق املدعي يف قبول أو عدم قبول مين املدعى عليه بنفي الدعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/30 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33470723 :‬‬\n                    ‫َر ْق ُم الدعوى‪33207246 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34227585‬تاريخه‪1434/5/29 :‬هـ‬\n\n\n ‫إيــذاء الغيــر (حــق خــاص) ‪ -‬اعتــداء بالضــرب ‪ -‬مطالبــة املدعــي‬\n ‫باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــي غيــر موصلــة ‪-‬‬\n ‫حــق املدعــي يف قبــول أو عــدم قبــول ميــن املدعــى عليــه بنفــي الدعــوى‬\n                                                              ‫‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                           ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بضربــه علــى وجهــه بيــده‪ ،‬وطلــب‬\n ‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء‬\n ‫يف الدعــوى‪ -‬أحضــر املدعــي شــاهد ًا فلــم تقبــل احملكمــة شــهادته‬\n ‫ألنهــا تضمنــت مــا يفيــد كونــه طرفــا يف اخلصومــة‪ -‬املدعــي لــم يقــم‬\n ‫بينــة موصلــة إلثبــات دعــواه ولــم يقبــل ميــن خصمــه علــى نفيهــا‪ -‬قضــت‬\n ‫احملكمــة بعــدم ثبــوت دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه منها‪-‬‬\n ‫قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                        ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n                                                                                     ‫‪232‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                                 ‫ّ‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 33207246‬وتاريــخ‬\n      ‫‪1433/03/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33550726‬وتاريــخ‬\n      ‫‪1433/03/22‬ه ـ ففــي يــوم األحــد املوافــق ‪1433/05/23‬ه ـ افتتحــت‬\n      ‫اجللســة االولــى الســاعة الثانيــة عشــر والنصــف وفيهــا حضــر (‪).....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).....‬وقــد جــرى طلــب‬\n      ‫املدعــى عليــه باخلطــاب رقــم ‪ 33/550726‬وتاريــخ ‪1433/3/30‬ه ـ‬\n      ‫فوردنــي إفــادة مديــر وحــدة اإلحضــار بهــذه احملكمــة برقــم ‪682‬‬\n      ‫وتاريــخ ‪1433/5/4‬ه ـ املتضمــن مــا نصــه ( نفيــد فضيلتكــم بأنــه مت‬\n      ‫طلــب املذكوريــن هاتفيــا واســتعد باحلضــور علــى حســب احملضــر‬\n      ‫املرفــق واملتضمــن مراجعــة فضيلــة القاضــي الشــيخ ‪ ).....(/‬باملوعــد‬\n      ‫احملــدد مــن فضيلتــه ) أ ‪.‬ه ـ وقــد وردنــي خطــاب املدعــى عليــه (‪).....‬‬\n      ‫املقيــد بهــذه احملكمــة برقــم ‪ 926434‬وتاريــخ ‪1433/5/17‬ه ـ‬\n      ‫املتضمــن مــا نصــه ( أقــدم لفضيلتكــم بخطابــي هــذا راجيــا مــن اهلل‬\n      ‫ثــم منكــم قبــول اعتــذاري مــن احلضــور للجلســة املقــررة لــدى فضيلــة‬\n      ‫الشــيخ بخصــوص دعــوى ضــدي يــوم األحــد املوافــق ‪1433/5/23‬ه ـ‬\n      ‫الســاعة العاشــرة والنصــف صباحــا حيــث أننــي خــارج البــاد بدولــة‬\n      ‫األردن ملناقشــة رســالة املاجســتير يف إحــدى اجلامعــات بــاألردن ) أ ‪ .‬ه ـ‬\n      ‫وبســؤال املدعــي عــن دعــواه قــرر قائــا بتاريــخ ‪1433/3/4‬ه ـ راجعــت‬\n      ‫مكتــب عمــدة قريــة ‪ ....‬وكان أخــوه يف مكتبــه فحصلــت بينــي وبــن‬\n\n‫‪233‬‬\n\f‫أخيــه مشــادة كالميــة فخــرج أخــاه وضربنــي كفــا علــى وجهــي لــذا‬\n‫اطلــب احلكــم علــى بحقــي الشــرعي هــذه دعــواي ولــدي أنــا ‪ ....‬القاضــي‬\n‫باحملكمــة اجلزائيــة باألحســاء القائــم بعمــل املكتــب القضائــي الثامــن‬\n‫املكلــف برقــم ‪ 33393416‬وتاريــخ ‪1433/06/10‬ه ـ ويف يــوم األحــد‬\n‫املوافــق ‪1433/7/20‬ه ـ افتتحــت اجللســة الثانيــة يف متــام الســاعة‬\n‫التاســعة اخلاصــة بدعــوى ضــد وفيهــا حضــر ‪ ...‬املدعــي وحضــر ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم بصفتــه وكيــا عــن املدعــى‬\n‫عليــه مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باإلحســاء‬\n‫برقــم ‪ 33172820‬وتاريــخ ‪1433/7/14‬ه ـ املخــول لــه يف املطالبــة‬\n‫وإقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى والــرد عليهــا‬\n‫واإلقــرار والصلــح والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع عنــه‬\n‫وإحضــار الشــهود والبينــات والطعــن فيهــا و اإلجابــة واجلــرح والتعديــل أ‪.‬‬\n‫ه ـ وبعــرض الدعــوى علــى املدعــى عليــه وكالــه أجــاب قائــا أن هــذه‬\n‫الدعــوى باطلــه وكيديــه واطلــب تعزيــر املدعــي لقــاء ذلــك هكــذا‬\n‫أجــاب وبســؤال املدعــي هــل لديــه بينــه علــى دعــواه أجــاب قائــا لــدي‬\n‫شــاهدين وهمــا و هكــذا أجــاب لــذا أجبتــه لطلبــه ورفعــت اجللســة‬\n‫ويف جلســة أخــرى وفيهــا حضــر املدعــي كمــا حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم وبعــرض الدعــوى علــى املدعــى عليــه أجــاب‬\n‫قائــا مــا ذكــره املدعــي غيــر صحيــح فلــم أضربــه كــف علــى وجــه‬\n‫وإمنــا تخاصــم املدعــي مــع أخــي وفرقــت بينهمــا هكــذا أجــاب وبعرضــه‬\n‫علــى املدعــي قــرر قائــا الصحيــح مــا ذكرتــه وبينتــي علــى ذلــك قــد‬\n‫أحضرتهــا وأطلــب ســماعها واطلــب ســماع مــا لــدي مــن شــهادة هكــذا‬\n‫قــرر ثــم احضــر الشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n                                                                                  ‫‪234‬‬\n\f      ‫املدنــي رقــم ‪ ...‬وقــرر قائــا اشــهد أن هــذا احلاضــر اتصــل علــى والــدي‬\n      ‫كــي نســتلم أوراق جمعيــة البــر اخليريــة يف قريــة ‪ ...‬ثــم حضــرت أنــا و‬\n      ‫إلــى مكتــب العمــدة هــذا احلاضــر فســألنا مــن طــرق البــاب فقلــت انــا‬\n      ‫الــذي طرقتــه فقــال إن مديــر شــرطة يســتدعيك ثــم دخــل اخــو العمــدة ثــم‬\n      ‫ســأل مــن طــرق البــاب فأجبتــه أنــا ثــم رفــع صوتــه وقــال إنكــم تكلمتــم‬\n      ‫علــى أهلــي وقــال نحــن نتكلــم مــع العمــدة ثــم رفــع صوتــه علــى وكان‬\n      ‫العمــدة يتحــدث مــع وأثنــاء ذلــك حصــل مشــادة بــن و ثــم قــام العمــدة‬\n      ‫بكــزه واخــرج أخــوه ورجــع إلــى ثــم ضربــه كــف بيــده اليمــن علــى‬\n      ‫خــده األيســر هــذا مــا لــدي وبــه اشــهد وبعــرض الشــاهد وشــهادته علــى‬\n      ‫املدعــى عليــه قــرر قائــا ال اعــرف عــن الشــاهد شــيء وشــهادته بعضهــا‬\n      ‫صحيــح وبعضهــا غيــر صحيــح والصحيــح انــي اتصلــت علــى والــده وقلــت‬\n      ‫لــه احضــر أنــت بنفســك لتســتلم املعاملــة التــي تخصــك فأتــوا ابنــاه‬\n      ‫وجلســوا عنــدي يف املكتــب ثــم ســألتهم عــن أســمائهم وعرفــت والدهــم‬\n      ‫وقلــت والدكــم صاحــب قــدمي وأنــا ســامحتكم وكنــت قبــل ذلــك أنــي‬\n      ‫اتصــل علــى شــرطة املبــرز وأخبرتهــم بــان فيــه أشــخاص تلفظــوا علــى‬\n      ‫أهلــي ونصحتهــم وكان حاضــرا شــاهدا وهــذا فقــط هــو الصحيــح أمــا‬\n      ‫بقيــة مــا ذكــره فغيــر صحيــح هكــذا قــرر وبســؤال املدعــي هــل لديــه‬\n      ‫زيــادة بينــه قــرر قائــا إن الشــاهد لــن يحضــر إلــى احملكمــة محتجــا‬\n      ‫بنســيان الشــهادة وال ســلطة لــي علــى إحضــاره هكــذا قــرر كمــا قــرر‬\n      ‫املدعــى عليــه قائــا إن الشــاهد أدلــى بشــهادته لــدى شــرطة ‪ ...‬واطلــب‬\n      ‫الرجــوع إليهــا هكــذا قــرر وبالرجــوع إليهــا اطلعــت علــى الصفحتــن‬\n      ‫‪ 14.15‬مــن اللفــة الثانيــة فوجدتهــا تتضمــن أقــوال الشــاهد املتضمنــة مــا‬\n      ‫نصــه (أفيدكــم انــه يف حوالــي الســاعة الثامنــة مســاء مــن يــوم اجلمعــة‬\n\n\n‫‪235‬‬\n\f‫املوافــق ‪1433/3/4‬ه ـ أثنــاء زيارتــي ملكتــب العمــدة بقصــد املراجعــة‬\n‫ويف أثنــاء جلوســي باملكتــب والعمــدة حضــر أبنــاء املدعــو وال اعلــم عــن‬\n‫ســبب مراجعتهــم وقــام العمــدة بــاألذن لهــم باجللــوس واحلديــث معهم حول‬\n‫معرفتــه لوالدهــم وانــا مســامحكم بالــذي حــدث منكــم وحدث كالم‬\n‫بينهــم حــول أنهــم كانــا يدرســان يف حلقة املســجد وبعدها حضر املدعو‬\n‫شــقيق العمــدة وقــام بالتحــدث مــع وحدثــت بينهــم مشــادة كالميــة فقــام‬\n‫العمــدة بالتدخــل بينهــم وفــك النــزاع حيــث قــام بدفــع أخيــه إلــى خــارج‬\n‫املكتــب وقــام بدفــع املدعــو بيــده اليمــن مــن قــوة التشــابك ممــا أدى‬\n‫ارتطــام يــده اليمنــى علــى وجهــه مــن اجلهــة اليمنــى وحســب مــا أراه انــه‬\n‫كان بقصــد فــك النــزاع ولــم يكــن القصــد االعتــداء) أ ‪ .‬ه ـ ويف جلســة‬\n‫أخــرى وفيهــا حضــر املدعــي واملدعــى عليــه وبعــرض مــا ورد يف أقــوال‬\n‫الشــاهد علــى املدعــي قــرر قائــا إن أقــوال الشــاهد متناقضــة وســمعته‬\n‫يقــول حصــل مشــادة كالميــة وضربنــي املدعــى عليــه ومــا هــو مــدون‬\n‫يقــول أن الضربــة حصلــت مــن غيــر قصــد لهــا واننــي قــد وكلــت أخــي‬\n‫هــذا احلاضــر يف املطالبــة واملدافعــة واملرافعــة واإلقــرار واإلنكار وإقامة‬\n‫الدعــوى والــرد عليهــا والصلــح والتنــازل وقبــول احلكــم واالعتــراض‬\n‫عليــه هكــذا قــرر كمــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ...‬وقــرر كل مــن املدعــي اصالــه ووكالــة قائــا أننــي ال‬\n‫أطالــب ميــن املدعــى عليــه علــى نفــي هــذه الدعــوى هكــذا قــرر وقــد‬\n‫قــرر املدعــى عليــه قائــا ان يــدي اليســرى أثنــاء تفريقــي بــن ضربــت‬\n‫رقبتــه هــذا كل مــا حصــل وبينــي وبــن الشــاهد خصومــه وهــو ســبب‬\n‫هــذه املشــكلة هكــذا قــرر فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة‬\n‫وإنــكار املدعــى عليــه للدعــوى نظــرا لكــون الشــاهد قــد ضمــن‬\n\n\n                                                                                    ‫‪236‬‬\n\f      ‫شــهادته مــا يفيــد بوجــود طــرف لــه يف هــذه اخلصومــة وبنــاء علــى مــا‬\n      ‫قــرره املدعــي مــن كونــه ليــس لــه اال هــذا الشــاهد وان الشــاهد اآلخــر‬\n      ‫احتــج بنســيان موضــوع الدعــوى ومــا قــرره املدعيــان أصالــة ووكالــة مــن‬\n      ‫عــدم طلــب اليمــن علــى نفــي الدعــوى وبنــاء علــى ذلــك كلــه فلــم تثبــت‬\n      ‫لــدي هــذه الدعــوى وأخليــت ســبيل املدعــى عليــه منهــا وبــه حكمــت‬\n      ‫وبعرضــه علــى الطرفــن قــرر املدعــي أصالــة ووكالــة عــدم قناعتهمــا بــه‬\n      ‫واســتعدا بتقــدمي الئحــة اعتراضيــه فأفهمتهمــا باملراجعــة يــوم األربعــاء‬\n      ‫املوافــق ‪1433/12/1‬ه ـ الســتالم نســخه مــن احلكــم لتقــدمي اعتراضــه‬\n      ‫عليــه يف مــده أقصاهــا شــهر مــن تاريخــه ففهمــا ذلــك وقــرر املدعــى عليــه‬\n      ‫قناعتــه بــه وأقفلــت اجللســة الســاعة الثانيــة عشــرة وخمســة وأربعــون‬\n      ‫دقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                     ‫وســلم حــرر يف ‪1433/11/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة االحســاء املكلف برقم‬\n      ‫‪ 33/2040703‬وتاريــخ ‪1434/4/28‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 341071814‬وتاريــخ ‪1434/5/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪33470723‬‬\n      ‫وتاريــخ ‪1433/11/30‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‪ ).....(/‬يف قضيــة‬\n      ‫اعتــداء علــى اخــر وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم حــرر يف ‪1434/5/29‬هــ‪.‬‬\n\n\n‫‪237‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":232,"source_page_end":237,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"556f4161c93d9707b377e4dc86f1827ab74680311fa739855410b76de9e73308","normalized_text_hash":"86deb04549e19d96bcfbc0f90b102a4626591ef75308b2f2d9b4acaa615055c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p232-33470723"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
